import type {
  ClockAdvanceSource,
  ClockAdvanceStatus,
  ClockDisplay,
  ClockLogEntry,
  NarrativeClock,
  ParsedNarrationTimestamp,
  StoryClockKind,
  StoryTime,
  StoryTimeAdvanceProposal,
  WorldMode,
} from './types';

export const EIGHT_BIT_TIME_RATIO = 8;
export const MAX_ORDINARY_REALITY_ADVANCE_MINUTES = 180;
export const MAX_CLOCK_LOG_ENTRIES = 30;

interface StoryTimeAdvanceOptions {
  source?: ClockAdvanceSource;
  reason?: string;
  sourceMessageId?: string;
  allowLongAdvance?: boolean;
  combatActive?: boolean;
}

export interface ClockApplyResult {
  clock: NarrativeClock;
  status: ClockAdvanceStatus;
  message: string;
  proposal?: StoryTimeAdvanceProposal;
  logEntry?: ClockLogEntry;
}

function nowClockIso(): string {
  return new Date().toISOString();
}

function createClockLogId(): string {
  const randomId =
    typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
      ? crypto.randomUUID()
      : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  return `clock-${randomId}`;
}

function normalizeMinuteValue(value: unknown): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return 0;
  return Math.max(0, Math.floor(value));
}

function normalizeMode(value: unknown, fallback: WorldMode): WorldMode {
  return value === 'reality' || value === 'eight_bit' ? value : fallback;
}

function normalizeLogEntry(raw: unknown): ClockLogEntry | null {
  if (!raw || typeof raw !== 'object') return null;
  const candidate = raw as Partial<ClockLogEntry>;
  const status =
    candidate.status === 'accepted' || candidate.status === 'rejected' || candidate.status === 'ignored'
      ? candidate.status
      : 'ignored';
  const source =
    candidate.source === 'ai' || candidate.source === 'manual' || candidate.source === 'event' || candidate.source === 'system'
      ? candidate.source
      : 'system';
  return {
    id: candidate.id || createClockLogId(),
    status,
    source,
    rawTimestamp: candidate.rawTimestamp || '',
    targetMode: candidate.targetMode === 'reality' || candidate.targetMode === 'eight_bit' ? candidate.targetMode : undefined,
    deltaMinutes: normalizeMinuteValue(candidate.deltaMinutes),
    realityDeltaMinutes: normalizeMinuteValue(candidate.realityDeltaMinutes),
    eightBitDeltaMinutes: normalizeMinuteValue(candidate.eightBitDeltaMinutes),
    reason: candidate.reason || '',
    message: candidate.message || '',
    sourceMessageId: candidate.sourceMessageId,
    createdAtIso: candidate.createdAtIso || nowClockIso(),
  };
}

function pushClockLog(clock: NarrativeClock, entry: ClockLogEntry): NarrativeClock {
  return {
    ...clock,
    log: [entry, ...(clock.log || [])].slice(0, MAX_CLOCK_LOG_ENTRIES),
  };
}

function createLogEntry(
  proposal: StoryTimeAdvanceProposal,
  status: ClockAdvanceStatus,
  message: string,
  realityDeltaMinutes = 0,
  eightBitDeltaMinutes = 0,
): ClockLogEntry {
  return {
    id: createClockLogId(),
    status,
    source: proposal.source,
    rawTimestamp: proposal.rawTimestamp,
    targetMode: proposal.targetMode,
    deltaMinutes: Math.max(0, proposal.deltaMinutes),
    realityDeltaMinutes,
    eightBitDeltaMinutes,
    reason: proposal.reason,
    message,
    sourceMessageId: proposal.sourceMessageId,
    createdAtIso: nowClockIso(),
  };
}

export function createInitialClock(mode: WorldMode = 'reality'): NarrativeClock {
  return {
    mode,
    realityMinutesElapsed: 0,
    eightBitMinutesElapsed: 0,
    log: [],
  };
}

export function normalizeClockState(raw: unknown, fallbackMode: WorldMode = 'reality'): NarrativeClock {
  if (!raw || typeof raw !== 'object') return createInitialClock(fallbackMode);
  const candidate = raw as Partial<NarrativeClock>;
  return {
    mode: normalizeMode(candidate.mode, fallbackMode),
    realityMinutesElapsed: normalizeMinuteValue(candidate.realityMinutesElapsed),
    eightBitMinutesElapsed: normalizeMinuteValue(candidate.eightBitMinutesElapsed),
    lastAiTimestamp: candidate.lastAiTimestamp,
    log: Array.isArray(candidate.log) ? candidate.log.map(normalizeLogEntry).filter(Boolean).slice(0, MAX_CLOCK_LOG_ENTRIES) as ClockLogEntry[] : [],
  };
}

export function switchClockMode(clock: NarrativeClock, mode: WorldMode): NarrativeClock {
  return {
    ...normalizeClockState(clock, mode),
    mode,
  };
}

export function convertRealityToEightBitTime(realityMinutes: number): number {
  return realityMinutes * EIGHT_BIT_TIME_RATIO;
}

export function convertEightBitToRealityTime(eightBitMinutes: number): number {
  return eightBitMinutes / EIGHT_BIT_TIME_RATIO;
}

export function parseAiTimestamp(rawText: string): string | undefined {
  const match = rawText.match(/\[(?:TIME|时间|时刻)\s*:\s*([^\]]+)\]/i);
  return match?.[1]?.trim();
}

function normalizeTimestampMode(rawMode: string): StoryClockKind | undefined {
  const mode = rawMode.trim().toLowerCase();
  if (mode === 'reality' || mode === 'real' || mode === '现实') return 'reality';
  if (mode === 'eight_bit' || mode === 'eightbit' || mode === '8bit' || mode === '8-bit' || mode === '像素') return 'eight_bit';
  return undefined;
}

function parseDurationToMinutes(amountText: string, unitText: string, signText: string): number {
  const amount = Number(amountText);
  if (!Number.isFinite(amount)) return Number.NaN;
  const unit = unitText.trim().toLowerCase();
  const multiplier = unit === 'h' || unit === 'hr' || unit === 'hour' || unit === 'hours' || unit === '小时' ? 60 : 1;
  return amount * multiplier * (signText === '-' ? -1 : 1);
}

export function parseNarrationTimestamp(rawText: string): ParsedNarrationTimestamp | undefined {
  const match = rawText.match(
    /\[(?:TIME|时间|时刻)\s*:\s*([a-zA-Z_\-0-9\u4e00-\u9fa5]+)\s*([+-])\s*(\d{1,5})\s*(m|min|minute|minutes|分钟|h|hr|hour|hours|小时)\s*\]/i,
  );
  if (!match) return undefined;

  const targetMode = normalizeTimestampMode(match[1]);
  if (!targetMode) return undefined;
  const deltaMinutes = parseDurationToMinutes(match[3], match[4], match[2]);
  if (!Number.isFinite(deltaMinutes)) return undefined;

  return {
    rawTimestamp: match[0],
    targetMode,
    deltaMinutes: Math.trunc(deltaMinutes),
  };
}

export function proposeStoryTimeAdvance(
  _current: NarrativeClock,
  rawText: string,
  options: StoryTimeAdvanceOptions = {},
): StoryTimeAdvanceProposal | undefined {
  const parsed = parseNarrationTimestamp(rawText);
  if (!parsed) return undefined;
  return {
    rawTimestamp: parsed.rawTimestamp,
    targetMode: parsed.targetMode,
    deltaMinutes: parsed.deltaMinutes,
    source: options.source || 'ai',
    reason: options.reason || '叙事时间戳',
    sourceMessageId: options.sourceMessageId,
    createdAtIso: nowClockIso(),
  };
}

function getRealityEquivalentDelta(proposal: StoryTimeAdvanceProposal): number {
  return proposal.targetMode === 'reality'
    ? proposal.deltaMinutes
    : convertEightBitToRealityTime(proposal.deltaMinutes);
}

function getAcceptedDeltas(clock: NarrativeClock, proposal: StoryTimeAdvanceProposal): {
  realityDeltaMinutes: number;
  eightBitDeltaMinutes: number;
} {
  if (proposal.targetMode === 'reality') {
    return {
      realityDeltaMinutes: proposal.deltaMinutes,
      eightBitDeltaMinutes: clock.mode === 'eight_bit' ? convertRealityToEightBitTime(proposal.deltaMinutes) : 0,
    };
  }

  if (clock.mode !== 'eight_bit') {
    return {
      realityDeltaMinutes: 0,
      eightBitDeltaMinutes: 0,
    };
  }

  return {
    realityDeltaMinutes: proposal.deltaMinutes === 0 ? 0 : Math.ceil(convertEightBitToRealityTime(proposal.deltaMinutes)),
    eightBitDeltaMinutes: proposal.deltaMinutes,
  };
}

export function acceptStoryTimeAdvance(
  clock: NarrativeClock,
  proposal: StoryTimeAdvanceProposal,
  options: StoryTimeAdvanceOptions = {},
): ClockApplyResult {
  const normalizedClock = normalizeClockState(clock, clock.mode);
  const timestampClock = proposal.source === 'ai'
    ? { ...normalizedClock, lastAiTimestamp: proposal.rawTimestamp }
    : normalizedClock;

  if (proposal.deltaMinutes < 0) {
    const entry = createLogEntry(proposal, 'rejected', '时间戳被拒绝：不能倒流时间。');
    return { clock: pushClockLog(timestampClock, entry), status: 'rejected', message: entry.message, proposal, logEntry: entry };
  }

  if (options.combatActive && proposal.deltaMinutes > 0) {
    const entry = createLogEntry(proposal, 'rejected', '时间戳被拒绝：战斗中不接受叙事跳时。');
    return { clock: pushClockLog(timestampClock, entry), status: 'rejected', message: entry.message, proposal, logEntry: entry };
  }

  if (proposal.targetMode === 'eight_bit' && timestampClock.mode !== 'eight_bit' && proposal.deltaMinutes > 0) {
    const entry = createLogEntry(proposal, 'rejected', '时间戳被拒绝：现实模式下 8bit 世界时间处于暂停。');
    return { clock: pushClockLog(timestampClock, entry), status: 'rejected', message: entry.message, proposal, logEntry: entry };
  }

  if (!options.allowLongAdvance && getRealityEquivalentDelta(proposal) > MAX_ORDINARY_REALITY_ADVANCE_MINUTES) {
    const entry = createLogEntry(proposal, 'rejected', '时间戳被拒绝：普通叙述不能一次跳过超过三小时的现实等价时间。');
    return { clock: pushClockLog(timestampClock, entry), status: 'rejected', message: entry.message, proposal, logEntry: entry };
  }

  const { realityDeltaMinutes, eightBitDeltaMinutes } = getAcceptedDeltas(timestampClock, proposal);
  const entry = createLogEntry(proposal, 'accepted', '时间戳已接受。', realityDeltaMinutes, eightBitDeltaMinutes);
  const advancedClock: NarrativeClock = {
    ...timestampClock,
    realityMinutesElapsed: timestampClock.realityMinutesElapsed + realityDeltaMinutes,
    eightBitMinutesElapsed: timestampClock.eightBitMinutesElapsed + eightBitDeltaMinutes,
  };
  return { clock: pushClockLog(advancedClock, entry), status: 'accepted', message: entry.message, proposal, logEntry: entry };
}

export function syncStoryTimeFromText(
  clock: NarrativeClock,
  rawText: string,
  options: StoryTimeAdvanceOptions = {},
): ClockApplyResult {
  const proposal = proposeStoryTimeAdvance(clock, rawText, options);
  if (!proposal) {
    return {
      clock: normalizeClockState(clock, clock.mode),
      status: 'ignored',
      message: '未发现合法时间戳。',
    };
  }
  return acceptStoryTimeAdvance(clock, proposal, options);
}

export function applyAiTimestamp(
  clock: NarrativeClock,
  rawText: string,
  options: Omit<StoryTimeAdvanceOptions, 'source'> = {},
): NarrativeClock {
  return syncStoryTimeFromText(clock, rawText, {
    ...options,
    source: 'ai',
    reason: options.reason || '正文叙述时间戳',
  }).clock;
}

export function advanceStoryTimeByEvent(
  clock: NarrativeClock,
  targetMode: StoryClockKind,
  deltaMinutes: number,
  reason: string,
): ClockApplyResult {
  const proposal: StoryTimeAdvanceProposal = {
    rawTimestamp: `[EVENT: ${targetMode} +${deltaMinutes}m]`,
    targetMode,
    deltaMinutes,
    source: 'event',
    reason,
    createdAtIso: nowClockIso(),
  };
  return acceptStoryTimeAdvance(clock, proposal, { allowLongAdvance: true });
}

export function minutesToStoryTime(kind: StoryClockKind, minutesElapsed: number): StoryTime {
  const normalizedMinutes = normalizeMinuteValue(minutesElapsed);
  const day = Math.floor(normalizedMinutes / 1440) + 1;
  const dayMinute = normalizedMinutes % 1440;
  const hour = Math.floor(dayMinute / 60);
  const minute = dayMinute % 60;
  const clockText = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
  return {
    kind,
    minutesElapsed: normalizedMinutes,
    day,
    hour,
    minute,
    label: `第 ${day} 日 ${clockText}`,
    totalLabel: `${normalizedMinutes} 分钟`,
  };
}

export function formatStoryMinutes(minutes: number): string {
  const normalizedMinutes = normalizeMinuteValue(minutes);
  const hours = Math.floor(normalizedMinutes / 60);
  const restMinutes = normalizedMinutes % 60;
  if (hours <= 0) return `${restMinutes} 分钟`;
  if (restMinutes === 0) return `${hours} 小时`;
  return `${hours} 小时 ${restMinutes} 分钟`;
}

export function getClockDisplay(clock: NarrativeClock): ClockDisplay {
  const normalizedClock = normalizeClockState(clock, clock.mode);
  return {
    mode: normalizedClock.mode,
    modeLabel: normalizedClock.mode === 'reality' ? '现实世界' : '8bit 世界',
    reality: minutesToStoryTime('reality', normalizedClock.realityMinutesElapsed),
    eightBit: minutesToStoryTime('eight_bit', normalizedClock.eightBitMinutesElapsed),
    lastAiTimestamp: normalizedClock.lastAiTimestamp,
    latestLog: normalizedClock.log[0],
    ratioLabel: `现实 1 分钟 = 8bit ${EIGHT_BIT_TIME_RATIO} 分钟`,
  };
}

export function getClockLog(clock: NarrativeClock): ClockLogEntry[] {
  return normalizeClockState(clock, clock.mode).log;
}
