import type { CombatActorStats, CombatDropReward, InventoryItemKind } from './types';
import { createId } from './save';

export type MonsterRole = 'starter' | 'fast' | 'status' | 'evasion' | 'defender' | 'magic' | 'elite' | 'boss';
export type MonsterPixelShape =
  | 'slime'
  | 'bat'
  | 'mushroom'
  | 'noise'
  | 'skeleton'
  | 'wisp'
  | 'imp'
  | 'mimic'
  | 'guardian'
  | 'knight'
  | 'shell'
  | 'lizard'
  | 'mirror';

export interface MonsterDropDefinition {
  itemId: string;
  name: string;
  kind: InventoryItemKind;
  chance: number;
  minCount: number;
  maxCount: number;
}

export interface MonsterSkillDefinition {
  id: string;
  name: string;
  description: string;
  weight: number;
  damageKind: 'physical' | 'magical' | 'support';
  multiplier: number;
  gaugeCost: number;
  hitModifier?: number;
  criticalModifier?: number;
  statusId?: 'poison' | 'speed_down' | 'evasion_up' | 'hardened';
  statusChance?: number;
}

export interface MonsterDefinition {
  id: string;
  name: string;
  level: number;
  role: MonsterRole;
  locationTags: string[];
  maxHp: number;
  stats: CombatActorStats;
  experience: number;
  gold: number;
  drops: MonsterDropDefinition[];
  skills: MonsterSkillDefinition[];
  pixel: {
    shape: MonsterPixelShape;
    color: string;
    accent: string;
    outline: string;
    animation: string;
  };
}

export interface EncounterTableEntry {
  monsterId: string;
  weight: number;
  minCount: number;
  maxCount: number;
}

export interface MonsterEncounter {
  id: string;
  locationId: string;
  name: string;
  monsterIds: string[];
}

function stats(input: Partial<CombatActorStats> & Pick<CombatActorStats, 'physicalAttack' | 'physicalDefense' | 'magicalAttack' | 'magicalDefense' | 'speed'>): CombatActorStats {
  return {
    hit: 82,
    evasionRate: 4,
    criticalRate: 4,
    criticalDamage: 150,
    statusAccuracy: 5,
    statusResistance: 5,
    healingPower: 0,
    ...input,
  };
}

