function randomInt(min: number, max: number): number {
  return min + Math.floor(Math.random() * (max - min + 1));
}

function pickWeighted<T extends { weight: number }>(items: T[]): T {
  const total = items.reduce((sum, item) => sum + item.weight, 0);
  let roll = Math.random() * total;
  for (const item of items) {
    roll -= item.weight;
    if (roll <= 0) return item;
  }
  return items[items.length - 1];
}

export function getMonster(monsterId: string): MonsterDefinition {
  const monster = MONSTER_DEFINITIONS.find(item => item.id === monsterId);
  if (!monster) throw Error(`未知怪物: ${monsterId}`);
  return monster;
}

export function getEncounterTable(locationId: string): EncounterTableEntry[] {
  return ENCOUNTER_TABLES[locationId] || [];
}

export function rollEncounter(locationId: string): MonsterEncounter {
  const table = getEncounterTable(locationId);
  if (!table.length) throw Error('当前地点没有可用遭遇表。');
  const entry = pickWeighted(table);
  const count = randomInt(entry.minCount, entry.maxCount);
  const monster = getMonster(entry.monsterId);
  return {
    id: createId('encounter'),
    locationId,
    name: count > 1 ? `${monster.name}群` : monster.name,
    monsterIds: Array.from({ length: count }, () => entry.monsterId),
  };
}

export function getMonsterRewards(monsterId: string): Pick<MonsterDefinition, 'experience' | 'gold' | 'drops'> {
  const monster = getMonster(monsterId);
  return {
    experience: monster.experience,
    gold: monster.gold,
    drops: monster.drops,
  };
}

export function rollMonsterDrops(monsterId: string): CombatDropReward[] {
  return getMonster(monsterId).drops.flatMap(drop => {
    if (Math.random() > drop.chance) return [];
    return [
      {
        itemId: drop.itemId,
        name: drop.name,
        kind: drop.kind,
        count: randomInt(drop.minCount, drop.maxCount),
      },
    ];
  });
}

export function pickMonsterSkill(monster: MonsterDefinition): MonsterSkillDefinition {
  return pickWeighted(monster.skills);
}
