const NPC_BY_ID = new Map(NPC_DEFINITIONS.map(npc => [npc.id, npc]));

export function createInitialNpcState(): NpcState {
  return {
    knownNpcIds: [],
    records: {},
    talkLog: [],
    generatedDraftLocationIds: [],
    flags: [],
  };
}

export function normalizeNpcState(raw: unknown): NpcState {
  const fallback = createInitialNpcState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<NpcState>;
  const records = Object.entries(candidate.records || {}).reduce<Record<string, NpcKnowledgeRecord>>((result, [npcId, record]) => {
    if (!NPC_BY_ID.has(npcId)) return result;
    result[npcId] = {
      npcId,
      discoveredAtIso: record.discoveredAtIso || nowIso(),
      lastTalkedAtIso: record.lastTalkedAtIso,
      talkCount: Math.max(0, Math.floor(record.talkCount || 0)),
      knownTopicIds: Array.from(new Set(record.knownTopicIds || [])),
      flags: Array.from(new Set(record.flags || [])),
    };
    return result;
  }, {});
  return {
    knownNpcIds: Array.from(new Set((candidate.knownNpcIds || []).filter(npcId => NPC_BY_ID.has(npcId)))),
    records,
    talkLog: (candidate.talkLog || []).filter(log => NPC_BY_ID.has(log.npcId)).slice(0, 30),
    generatedDraftLocationIds: Array.from(new Set(candidate.generatedDraftLocationIds || [])),
    lastSceneDraft: candidate.lastSceneDraft,
    flags: Array.from(new Set(candidate.flags || [])),
  };
}

export function getNpcDefinition(npcId: string): NpcDefinition | undefined {
  return NPC_BY_ID.get(npcId);
}

export function getLocationNpcDefinitions(locationId: string): NpcDefinition[] {
  return NPC_DEFINITIONS.filter(npc => npc.locationId === locationId);
}

export function getNpcViews(save: GameSave, locationId = save.map.currentLocationId): NpcView[] {
  return getLocationNpcDefinitions(locationId).map(definition => {
    const record = save.npc.records[definition.id];
    return {
      definition,
      record,
      topics: definition.topics,
      locationName: getLocationDefinition(definition.locationId)?.name || definition.locationId,
      known: save.npc.knownNpcIds.includes(definition.id),
      talked: Boolean(record?.lastTalkedAtIso),
    };
  });
}

function getNpcTopic(npc: NpcDefinition, topicId?: string): NpcTopicDefinition {
  const topic = topicId ? npc.topics.find(item => item.id === topicId) : npc.topics[0];
  if (!topic) throw Error('未知 NPC 话题。');
  return topic;
}

export function contactNpc(save: GameSave, npcId: string): NpcContactResult {
  const npc = getNpcDefinition(npcId);
  if (!npc) throw Error('未知 NPC。');
  if (save.map.currentLocationId !== npc.locationId) throw Error('该 NPC 不在当前位置。');
  const existing = save.npc.records[npc.id];
  const timestamp = nowIso();
  const record: NpcKnowledgeRecord = {
    npcId: npc.id,
    discoveredAtIso: existing?.discoveredAtIso || timestamp,
    lastTalkedAtIso: existing?.lastTalkedAtIso,
    talkCount: existing?.talkCount || 0,
    knownTopicIds: Array.from(new Set(existing?.knownTopicIds || [])),
    flags: Array.from(new Set(existing?.flags || [])),
  };
  return {
    save: {
      ...save,
      npc: {
        ...save.npc,
        knownNpcIds: Array.from(new Set([...save.npc.knownNpcIds, npc.id])),
        records: {
          ...save.npc.records,
          [npc.id]: record,
        },
      },
    },
    npc,
  };
}

export function talkToNpc(save: GameSave, npcId: string, topicId?: string): NpcTalkResult {
  const npc = getNpcDefinition(npcId);
  if (!npc) throw Error('未知 NPC。');
  if (save.map.currentLocationId !== npc.locationId) throw Error('该 NPC 不在当前位置。');
  const topic = getNpcTopic(npc, topicId);
  const companionFlags = ['first_companion_lia', 'first_companion_leon'];
  if (topic.unlockFlag && companionFlags.includes(topic.unlockFlag)) {
    const selected = save.npc.flags.find(flag => companionFlags.includes(flag));
    if (selected && selected !== topic.unlockFlag) {
      throw Error('已经记录了另一位固定伙伴；第一版只允许从双胞胎中选择一位同行者。');
    }
  }
  const existing = save.npc.records[npc.id];
  const timestamp = nowIso();
  const knownTopicIds = Array.from(new Set([...(existing?.knownTopicIds || []), topic.id]));
  const record: NpcKnowledgeRecord = {
    npcId: npc.id,
    discoveredAtIso: existing?.discoveredAtIso || timestamp,
    lastTalkedAtIso: timestamp,
    talkCount: (existing?.talkCount || 0) + 1,
    knownTopicIds,
    flags: Array.from(new Set([...(existing?.flags || []), ...(topic.unlockFlag ? [topic.unlockFlag] : [])])),
  };
  const nextState: NpcState = {
    ...save.npc,
    knownNpcIds: Array.from(new Set([...save.npc.knownNpcIds, npc.id])),
    records: {
      ...save.npc.records,
      [npc.id]: record,
    },
    talkLog: [
      {
        id: createId('talk'),
        npcId: npc.id,
        npcName: npc.name,
        topicId: topic.id,
        topicLabel: topic.label,
        locationId: npc.locationId,
        summary: topic.summary,
        createdAtIso: timestamp,
      },
      ...save.npc.talkLog,
    ].slice(0, 30),
    flags: Array.from(new Set([...save.npc.flags, ...(topic.unlockFlag ? [topic.unlockFlag] : [])])),
  };

  return {
    save: {
      ...save,
      npc: nextState,
    },
    npc,
    topic,
    questEvent: topic.questEvent,
  };
}

export function buildSceneNpcDraftPrompt(save: GameSave, locationId = save.map.currentLocationId): string {
  const location = getLocationDefinition(locationId) || getCurrentLocation(save);
  const existingNpcs = getLocationNpcDefinitions(location.id);
  const mainQuest = getActiveMainQuest(save);
  const worldbookRecords = save.worldbookMemory.records
    .slice(-8)
    .map(record => `- ${record.entryName}: ${record.contentPreview}`)
    .join('\n');

  return [
    '你正在为互动游戏《8bit的幻想》生成场景 NPC 世界书草案。',
    '目标：为当前地点补充 1 到 3 名可互动 NPC，供用户确认后写入当前存档世界书。',
    '硬规则：NPC 可以提供对白、传闻、生活细节和剧情钩子，但不能直接结算经验、金币、掉落、任务完成、地图移动或装备变化。',
    '硬规则：莱姆是女性魔王，但她的详细人设、大结局和最终决战核心文本留空，不能擅自补完。',
    '输出格式：写成一条可直接放入世界书的中文条目。包含 NPC 名字、身份、性格、可聊话题、与当前地点/任务的关系、禁止越权结算说明。不用 JSON。',
    '',
    `当前地点：${location.name} / ${location.region}`,
    `地点描述：${location.description}`,
    `地图提示：${location.mapHint}`,
    `当前主线：${mainQuest?.definition.name || '无'} / ${getQuestHint(save)}`,
    '',
    '已有固定 NPC：',
    existingNpcs.length ? existingNpcs.map(npc => `- ${npc.name}（${npc.title}）：${npc.description}`).join('\n') : '- 无',
    '',
    '近期世界书记录：',
    worldbookRecords || '- 无',
  ].join('\n');
}

export async function generateSceneNpcDraft(save: GameSave, locationId = save.map.currentLocationId): Promise<GameSave> {
  const location = getLocationDefinition(locationId);
  if (!location) throw Error('未知地点。');
  const content = await generateWithProfile(save.api, 'npc_generation', {
    systemPrompt: buildSceneNpcDraftPrompt(save, locationId),
    userInput: `请为 ${location.name} 生成场景 NPC 世界书草案。`,
    maxChatHistory: 0,
  });
  const draftSave = createWorldbookDraft(save, {
    kind: 'npc',
    entryName: `8bit的幻想: ${location.name} 场景NPC草案`,
    content,
  });
  const draft = draftSave.worldbookMemory.drafts[draftSave.worldbookMemory.drafts.length - 1];
  const timestamp = nowIso();
  return recordMessage(
    {
      ...draftSave,
      npc: {
        ...draftSave.npc,
        generatedDraftLocationIds: Array.from(new Set([...draftSave.npc.generatedDraftLocationIds, locationId])),
        lastSceneDraft: draft
          ? {
              draftId: draft.id,
              locationId,
              createdAtIso: timestamp,
            }
          : draftSave.npc.lastSceneDraft,
      },
    },
    'assistant',
    content,
  );
}
