import type {
  GameSave,
  PlayerAttributeBlock,
  PlayerDerivedStats,
  PlayerState,
  PlayerStatsSnapshot,
  WorldMode,
} from './types';
import { createEmptyProfessionPoints, createInitialProfessionState, getProfessionAttributeBonus } from './professions';
import { createInitialSkillState } from './skills';
import { getEquipmentAttributeBonus } from './equipment';

export const ATTRIBUTE_LABELS: Record<keyof PlayerAttributeBlock, string> = {
  strength: '力量',
  constitution: '体质',
  intelligence: '智力',
  spirit: '精神',
  agility: '敏捷',
  technique: '技巧',
  luck: '幸运',
  will: '意志',
};

export function createEmptyAttributeBlock(value = 0): PlayerAttributeBlock {
  return {
    strength: value,
    constitution: value,
    intelligence: value,
    spirit: value,
    agility: value,
    technique: value,
    luck: value,
    will: value,
  };
}

export function createInitialBaseAttributes(): PlayerAttributeBlock {
  return {
    strength: 6,
    constitution: 6,
    intelligence: 6,
    spirit: 6,
    agility: 6,
    technique: 6,
    luck: 5,
    will: 7,
  };
}

function addAttributeBlocks(...blocks: Partial<PlayerAttributeBlock>[]): PlayerAttributeBlock {
  const result = createEmptyAttributeBlock();
  blocks.forEach(block => {
    Object.keys(result).forEach(key => {
      const attributeKey = key as keyof PlayerAttributeBlock;
      result[attributeKey] += block[attributeKey] || 0;
    });
  });
  return result;
}

function round(value: number): number {
  return Math.max(0, Math.round(value));
}

function clamp(min: number, max: number, value: number): number {
  return Math.min(max, Math.max(min, value));
}

export function softValue(value: number, scale: number): number {
  const safeValue = Math.max(0, value);
  return safeValue / (safeValue + scale);
}

function computeDerivedStats(player: PlayerState, effective: PlayerAttributeBlock): PlayerDerivedStats {
  const level = player.level;
  const speed = 100 + 160 * softValue(effective.agility, 160) + 60 * softValue(effective.technique, 160);
  const evasionRate = clamp(0, 45, 5 + 28 * softValue(effective.agility, 180) + 12 * softValue(effective.luck, 220));
  const criticalRate = clamp(
    3,
    35,
    4 + 18 * softValue(effective.technique, 220) + 10 * softValue(effective.luck, 260),
  );

  return {
    maxHp: round(80 + level * 8 + effective.constitution * 12 + effective.will * 3 + player.vitalGrowth.hp),
    maxMp: round(20 + level * 3 + effective.intelligence * 5 + effective.spirit * 7 + player.vitalGrowth.mp),
    physicalAttack: round(effective.strength * 2.2 + effective.technique * 0.4 + level * 0.8),
    physicalDefense: round(effective.constitution * 1.8 + effective.strength * 0.4 + level * 0.5),
    magicalAttack: round(effective.intelligence * 2.1 + effective.spirit * 0.4 + level * 0.7),
    magicalDefense: round(effective.spirit * 1.8 + effective.constitution * 0.5 + level * 0.5),
    speed: round(speed),
    hit: round(80 + effective.technique * 0.35 + effective.agility * 0.12 + effective.luck * 0.08),
    evasionRate: Number(evasionRate.toFixed(2)),
    criticalRate: Number(criticalRate.toFixed(2)),
    criticalDamage: Number((150 + Math.min(50, softValue(effective.technique, 220) * 35 + softValue(effective.luck, 260) * 15)).toFixed(2)),
    statusAccuracy: round(effective.intelligence * 0.12 + effective.technique * 0.16 + effective.luck * 0.08),
    statusResistance: round(effective.spirit * 0.18 + effective.will * 0.2 + effective.luck * 0.05),
    healingPower: round(effective.spirit * 1.5 + effective.intelligence * 0.4 + level * 0.5),
    actionRecovery: round(6 + effective.will * 0.12 + effective.spirit * 0.08),
  };
}

export function getPlayerStats(save: GameSave): PlayerStatsSnapshot | null {
  const player = save.playerState;
  if (!player) return null;
  const professionBonus = getProfessionAttributeBonus(player);
  const equipmentBonus = getEquipmentAttributeBonus(save);
  const effectiveAttributes = addAttributeBlocks(player.baseAttributes, player.levelGrowth, professionBonus, equipmentBonus);
  return {
    baseAttributes: player.baseAttributes,
    levelGrowth: player.levelGrowth,
    professionBonus,
    equipmentBonus,
    effectiveAttributes,
    derived: computeDerivedStats(player, effectiveAttributes),
  };
}

export function createInitialPlayerState(): PlayerState {
  const baseAttributes = createInitialBaseAttributes();
  const player: PlayerState = {
    level: 1,
    experience: 0,
    totalExperience: 0,
    currentHp: 1,
    currentMp: 1,
    baseAttributes,
    levelGrowth: createEmptyAttributeBlock(),
    vitalGrowth: { hp: 0, mp: 0 },
    unspentAttributePoints: 0,
    professionPoints: createEmptyProfessionPoints(),
    unspentProfessionPoints: 0,
    professions: createInitialProfessionState(),
    skills: createInitialSkillState(),
    presentationMode: 'reality',
    experienceLog: [],
  };
  const stats = computeDerivedStats(player, baseAttributes);
  return {
    ...player,
    currentHp: stats.maxHp,
    currentMp: stats.maxMp,
  };
}

export function normalizePlayerState(raw: unknown): PlayerState {
  const fallback = createInitialPlayerState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<PlayerState>;
  const professions = candidate.professions || fallback.professions;
  const skills = candidate.skills || fallback.skills;

  const player: PlayerState = {
    ...fallback,
    ...candidate,
    level: Math.max(1, Math.floor(candidate.level ?? fallback.level)),
    experience: Math.max(0, Math.floor(candidate.experience ?? 0)),
    totalExperience: Math.max(0, Math.floor(candidate.totalExperience ?? 0)),
    currentHp: Math.max(0, Math.floor(candidate.currentHp ?? fallback.currentHp)),
    currentMp: Math.max(0, Math.floor(candidate.currentMp ?? fallback.currentMp)),
    baseAttributes: { ...fallback.baseAttributes, ...candidate.baseAttributes },
    levelGrowth: { ...fallback.levelGrowth, ...candidate.levelGrowth },
    vitalGrowth: { ...fallback.vitalGrowth, ...candidate.vitalGrowth },
    professionPoints: { ...fallback.professionPoints, ...candidate.professionPoints },
    professions: {
      ...fallback.professions,
      ...professions,
      unlocked: Array.from(new Set(['hero', ...(professions.unlocked || [])])),
      flags: Array.from(new Set(professions.flags || [])),
      rankByProfession: {
        ...fallback.professions.rankByProfession,
        ...(professions.rankByProfession || {}),
      },
    },
    skills: {
      ...fallback.skills,
      ...skills,
      knownHeroSkillIds: Array.from(new Set(['hero_strike', 'hero_guard', ...(skills.knownHeroSkillIds || [])])),
      knownProfessionSkillIds: Array.from(new Set(skills.knownProfessionSkillIds || [])),
      loadoutSkillIds: Array.from(new Set(skills.loadoutSkillIds || fallback.skills.loadoutSkillIds)),
    },
    experienceLog: candidate.experienceLog || [],
  };

  const stats = computeDerivedStats(player, addAttributeBlocks(player.baseAttributes, player.levelGrowth, getProfessionAttributeBonus(player)));
  return {
    ...player,
    currentHp: clamp(0, stats.maxHp, player.currentHp),
    currentMp: clamp(0, stats.maxMp, player.currentMp),
  };
}

export function ensurePlayerState(save: GameSave): GameSave {
  if (save.playerState) return { ...save, playerState: normalizePlayerState(save.playerState) };
  return { ...save, playerState: createInitialPlayerState() };
}

export function applyDamageToPlayer(save: GameSave, amount: number): GameSave {
  const nextSave = ensurePlayerState(save);
  const player = nextSave.playerState!;
  return {
    ...nextSave,
    playerState: {
      ...player,
      currentHp: Math.max(0, player.currentHp - Math.max(0, Math.floor(amount))),
    },
  };
}

export function healPlayer(save: GameSave, amount: number): GameSave {
  const nextSave = ensurePlayerState(save);
  const player = nextSave.playerState!;
  const stats = getPlayerStats(nextSave);
  return {
    ...nextSave,
    playerState: {
      ...player,
      currentHp: Math.min(stats?.derived.maxHp || player.currentHp, player.currentHp + Math.max(0, Math.floor(amount))),
    },
  };
}

export function restorePlayerVitals(save: GameSave): GameSave {
  const nextSave = ensurePlayerState(save);
  const stats = getPlayerStats(nextSave);
  if (!stats) return nextSave;
  return {
    ...nextSave,
    playerState: {
      ...nextSave.playerState!,
      currentHp: stats.derived.maxHp,
      currentMp: stats.derived.maxMp,
    },
  };
}

export function transformPlayerPresentation(save: GameSave, mode: WorldMode): GameSave {
  if (!save.playerState) return save;
  return {
    ...save,
    playerState: {
      ...save.playerState,
      presentationMode: mode,
    },
  };
}
