`, "",{"version":3,"sources":["webpack://./src/8bit的幻想/脚本/控制台/components/combat/CombatPanel.vue"],"names":[],"mappings":"AAsPA,+BACE,iBAAkB,CAClB,YAAa,CACb,QACF,CAEA,sCACE,iBAAkB,CAClB,iBAAkB,CAClB,SAAU,CACV,YAAa,CACb,kBAAmB,CACnB,mBACF,CAEA,uCACE,WAAY,CACZ,YAAa,CACb,2BAA4B,CAC5B,2BAA4B,CAC5B,uBAAwB,CACxB,qDACF,CAEA,oDACE,mCAAoC,CACpC,kDACF,CAEA,oDACE,qBAAsB,CACtB,kDACF,CAEA,mDACE,qBAAsB,CACtB,mDACF,CAEA,wCACE,KACE,uBACF,CACA,GACE,4BACF,CACF,CAEA,+BACE,YAAa,CACb,OAAQ,CACR,qBAAsB,CACtB,eAAgB,CAChB,+BAAmC,CACnC,oCACF,CAEA,iCACE,aAAc,CACd,qBAAuB,CACvB,WAAY,CACZ,qBAAsB,CACtB,kBAAmB,CACnB,mBAAoB,CACpB,kDACF","sourcesContent":["<script setup lang=\"ts\">\nimport { SKILL_DEFINITIONS } from '../../core/skills';\nimport { useGameStore, type SkillId } from '../../stores/gameStore';\nimport { monsters as monsterSprites, fx, ui as uiAssets } from '../../assets';\n\nconst game = useGameStore();\nconst selectedTargetId = ref('');\n\ntype CombatEffectKind = 'slash' | 'magic' | 'heal';\n\nconst effectUrls: Record<CombatEffectKind, string> = {\n  slash: fx.slash,\n  magic: fx.magic,\n  heal: fx.heal,\n};\n\nconst victoryTextUrl = uiAssets.victory;\n\nconst activeEffect = ref<{ key: number; kind: CombatEffectKind } | null>(null);\nlet effectTimer: ReturnType<typeof window.setTimeout> | null = null;\n\nconst combat = computed(() => game.combat);\nconst player = computed(() => combat.value?.actors.find(actor => actor.id === 'player') || null);\nconst enemies = computed(() => combat.value?.actors.filter(actor => actor.side === 'enemy') || []);\nconst livingEnemies = computed(() => enemies.value.filter(actor => actor.alive && actor.currentHp > 0));\nconst canAct = computed(() => combat.value?.active && combat.value.phase === 'awaiting_player');\nconst playerSkills = computed(() => {\n  const ids = player.value?.skillIds || [];\n  return ids\n    .map(skillId => SKILL_DEFINITIONS.find(skill => skill.id === skillId))\n    .filter((skill): skill is (typeof SKILL_DEFINITIONS)[number] => Boolean(skill));\n});\n\nwatch(\n  livingEnemies,\n  enemiesNow => {\n    if (!enemiesNow.length) {\n      selectedTargetId.value = '';\n      return;\n    }\n    if (!enemiesNow.some(enemy => enemy.id === selectedTargetId.value)) selectedTargetId.value = enemiesNow[0].id;\n  },\n  { immediate: true },\n);\n\nfunction hpPercent(current: number, max: number) {\n  if (!max) return 0;\n  return Math.max(0, Math.min(100, (current / max) * 100));\n}\n\nfunction gaugePercent(gauge: number) {\n  return Math.max(0, Math.min(100, (gauge / 10000) * 100));\n}\n\nfunction playCombatEffect(kind: CombatEffectKind) {\n  const key = Date.now();\n  if (effectTimer) window.clearTimeout(effectTimer);\n  activeEffect.value = { key, kind };\n  effectTimer = window.setTimeout(() => {\n    if (activeEffect.value?.key === key) activeEffect.value = null;\n  }, 560);\n}\n\nfunction effectForSkill(skillId: SkillId): CombatEffectKind {\n  const skill = SKILL_DEFINITIONS.find(item => item.id === skillId);\n  if (!skill) return 'slash';\n  if (skill.tags.some(tag => ['治疗', '净化', '防御', '护卫', '辅助'].includes(tag))) return 'heal';\n  if (skill.tags.some(tag => ['火', '蓄力'].includes(tag))) return 'magic';\n  return 'slash';\n}\n\nfunction submitAttack() {\n  if (!selectedTargetId.value) return;\n  playCombatEffect('slash');\n  game.submitCombatCommand({ kind: 'attack', targetId: selectedTargetId.value });\n}\n\nfunction submitGuard() {\n  playCombatEffect('heal');\n  game.submitCombatCommand({ kind: 'guard' });\n}\n\nfunction submitEscape() {\n  game.submitCombatCommand({ kind: 'escape' });\n}\n\nfunction submitSkill(skillId: SkillId) {\n  playCombatEffect(effectForSkill(skillId));\n  game.submitCombatCommand({ kind: 'skill', skillId, targetId: selectedTargetId.value });\n}\n</script>\n\n<template>\n  <section class=\"combat-panel\" aria-label=\"战斗\">\n    <!-- Battle header -->\n    <div style=\"display:flex;align-items:center;justify-content:space-between;gap:12px;\">\n      <div>\n        <div style=\"font-size:10px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:var(--p5-red);\">BATTLE</div>\n        <div style=\"font-size:16px;font-weight:900;margin-top:2px;\">{{ combat?.active ? '遭遇战进行中' : '遭遇战' }}</div>\n      </div>\n      <button class=\"action-btn primary\" :disabled=\"game.isBusy || !game.canStartEncounter\" @click=\"game.startEncounter\">\n        <svg viewBox=\"0 0 24 24\" style=\"width:14px;height:14px;\"><path d=\"M14.5 17.5L3 6V3h3l11.5 11.5\"/><path d=\"M13 19l6-6\"/></svg>\n        遭遇\n      </button>\n    </div>\n\n    <div style=\"font-size:12px;color:var(--p5-gray-dim);\">{{ game.combatSummary }}</div>\n\n    <div class=\"combat-effect-layer\" aria-hidden=\"true\">\n      <div\n        v-if=\"activeEffect\"\n        :key=\"activeEffect.key\"\n        class=\"combat-sprite-effect\"\n        :class=\"`effect-${activeEffect.kind}`\"\n        :style=\"{ backgroundImage: `url(${effectUrls[activeEffect.kind]})` }\"\n      ></div>\n    </div>\n\n    <!-- Victory -->\n    <div v-if=\"combat?.phase === 'victory' && combat.lastRewards\" class=\"victory-card\">\n      <img class=\"victory-banner\" :src=\"victoryTextUrl\" alt=\"VICTORY\" />\n      <div style=\"display:flex;flex-wrap:wrap;gap:8px;font-size:13px;\">\n        <span style=\"color:var(--p5-gold);font-weight:700;\">{{ combat.lastRewards.experience }} EXP</span>\n        <span style=\"color:var(--p5-gold);font-weight:700;\">{{ combat.lastRewards.gold }} G</span>\n        <span v-if=\"combat.lastRewards.drops.length\" style=\"color:var(--p5-white);\">\n          {{ combat.lastRewards.drops.map(drop => `${drop.name} x${drop.count}`).join(', ') }}\n        </span>\n      </div>\n    </div>\n\n    <!-- Defeat -->\n    <div v-if=\"combat?.phase === 'defeat' && combat.defeatPenalty\" style=\"padding:12px;border-left:4px solid var(--p5-hp);background:rgba(255,51,68,0.06);\">\n      <div style=\"font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--p5-hp);margin-bottom:4px;\">DEFEAT</div>\n      <div style=\"font-size:13px;\">\n        <span style=\"color:var(--p5-hp);\">-{{ combat.defeatPenalty.lostExperience }} EXP</span>\n        <span style=\"margin-left:8px;\">复活: {{ combat.defeatPenalty.revivedAtLocationId }}</span>\n      </div>\n    </div>\n\n    <!-- Battle field -->\n    <template v-if=\"combat?.active\">\n      <!-- Player status -->\n      <div v-if=\"player\" class=\"data-card\">\n        <div style=\"display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-weight:800;\">{{ player.name }}</span>\n          <span style=\"font-size:11px;color:var(--p5-gray-dim);\">Lv.{{ player.level }}</span>\n        </div>\n        <div class=\"stat-bar\" style=\"margin-top:6px;\">\n          <span class=\"stat-bar-label\" style=\"color:var(--p5-hp);min-width:20px;\">HP</span>\n          <div class=\"stat-bar-track\"><div class=\"stat-bar-fill hp\" :style=\"{ width: hpPercent(player.currentHp, player.maxHp) + '%' }\"></div></div>\n          <span class=\"stat-bar-num\">{{ player.currentHp }}/{{ player.maxHp }}</span>\n        </div>\n        <div class=\"stat-bar\">\n          <span class=\"stat-bar-label\" style=\"color:var(--p5-mp);min-width:20px;\">MP</span>\n          <div class=\"stat-bar-track\"><div class=\"stat-bar-fill mp\" :style=\"{ width: hpPercent(player.currentMp || 0, player.maxMp || 1) + '%' }\"></div></div>\n          <span class=\"stat-bar-num\">{{ player.currentMp || 0 }}/{{ player.maxMp || 0 }}</span>\n        </div>\n        <div class=\"stat-bar\">\n          <span class=\"stat-bar-label\" style=\"color:var(--p5-safe);min-width:20px;\">GA</span>\n          <div class=\"stat-bar-track\"><div class=\"stat-bar-fill gauge\" :style=\"{ width: gaugePercent(player.gauge) + '%' }\"></div></div>\n          <span class=\"stat-bar-num\">{{ Math.floor(player.gauge) }}</span>\n        </div>\n        <div v-if=\"player.statuses.length\" style=\"font-size:11px;color:var(--p5-gold);margin-top:4px;\">{{ player.statuses.map(s => s.label).join(', ') }}</div>\n      </div>\n\n      <!-- Enemy grid -->\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:6px;\">\n        <button\n          v-for=\"enemy in enemies\"\n          :key=\"enemy.id\"\n          type=\"button\"\n          class=\"data-card\"\n          :style=\"{\n            cursor: enemy.alive ? 'pointer' : 'default',\n            opacity: enemy.alive ? 1 : 0.3,\n            borderColor: selectedTargetId === enemy.id ? 'var(--p5-red)' : 'var(--border-subtle)',\n            background: selectedTargetId === enemy.id ? 'rgba(232,0,42,0.08)' : undefined,\n          }\"\n          :disabled=\"!enemy.alive\"\n          @click=\"enemy.alive && (selectedTargetId = enemy.id)\"\n        >\n          <!-- Monster sprite -->\n          <div style=\"width:56px;height:56px;margin:0 auto 4px;display:grid;place-items:center;overflow:hidden;\">\n            <img\n              v-if=\"enemy.monsterId && monsterSprites[enemy.monsterId]\"\n              :src=\"monsterSprites[enemy.monsterId]\"\n              :alt=\"enemy.name\"\n              style=\"width:100%;height:100%;object-fit:contain;\"\n            />\n            <svg v-else viewBox=\"0 0 24 24\" style=\"width:32px;height:32px;fill:none;stroke:var(--p5-hp);stroke-width:2;\">\n              <circle cx=\"12\" cy=\"12\" r=\"10\"/>\n              <circle cx=\"9\" cy=\"10\" r=\"1.5\" fill=\"var(--p5-hp)\"/>\n              <circle cx=\"15\" cy=\"10\" r=\"1.5\" fill=\"var(--p5-hp)\"/>\n              <path d=\"M8 15s1.5 2 4 2 4-2 4-2\"/>\n            </svg>\n          </div>\n          <div style=\"font-weight:700;font-size:12px;text-align:center;\">{{ enemy.name }}</div>\n          <div style=\"font-size:10px;color:var(--p5-gray-dim);text-align:center;\">Lv.{{ enemy.level }}</div>\n          <div class=\"stat-bar\" style=\"margin-top:4px;\">\n            <div class=\"stat-bar-track\"><div class=\"stat-bar-fill hp\" :style=\"{ width: hpPercent(enemy.currentHp, enemy.maxHp) + '%' }\"></div></div>\n          </div>\n          <div style=\"font-size:9px;color:var(--p5-gray-dim);text-align:center;margin-top:2px;\">{{ enemy.currentHp }}/{{ enemy.maxHp }}</div>\n        </button>\n      </div>\n\n      <!-- P5 Action bar -->\n      <div style=\"display:flex;gap:4px;\">\n        <button class=\"action-btn primary\" :disabled=\"game.isBusy || !canAct || !selectedTargetId\" @click=\"submitAttack\" style=\"flex:1;\">\n          <svg viewBox=\"0 0 24 24\" style=\"width:14px;height:14px;\"><path d=\"M14.5 17.5L3 6V3h3l11.5 11.5\"/></svg>\n          攻击\n        </button>\n        <button class=\"action-btn\" :disabled=\"game.isBusy || !canAct\" @click=\"submitGuard\" style=\"flex:1;\">\n          <svg viewBox=\"0 0 24 24\" style=\"width:14px;height:14px;\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\n          防御\n        </button>\n        <button class=\"action-btn\" :disabled=\"game.isBusy || !canAct\" @click=\"submitEscape\" style=\"flex:1;\">\n          <svg viewBox=\"0 0 24 24\" style=\"width:14px;height:14px;\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n          逃跑\n        </button>\n      </div>\n\n      <!-- Skills -->\n      <div v-if=\"playerSkills.length\" style=\"display:flex;flex-wrap:wrap;gap:4px;\">\n        <button\n          v-for=\"skill in playerSkills\"\n          :key=\"skill.id\"\n          class=\"action-btn gold\"\n          style=\"font-size:11px;padding:4px 10px;\"\n          :disabled=\"game.isBusy || !canAct\"\n          @click=\"submitSkill(skill.id)\"\n        >\n          {{ skill.name }}\n        </button>\n      </div>\n    </template>\n\n    <!-- Battle log -->\n    <div style=\"max-height:140px;overflow-y:auto;padding:8px;background:rgba(255,255,255,0.02);border:1px solid var(--border-subtle);font-size:12px;\">\n      <div style=\"font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--p5-gray-dim);margin-bottom:6px;\">LOG</div>\n      <p v-for=\"entry in combat?.log || []\" :key=\"entry.id\" :style=\"{ margin:'2px 0', color: entry.tone === 'good' ? 'var(--p5-safe)' : entry.tone === 'bad' ? 'var(--p5-hp)' : entry.tone === 'reward' ? 'var(--p5-gold)' : 'var(--p5-gray)' }\">{{ entry.text }}</p>\n      <p v-if=\"!combat?.log.length\" style=\"color:var(--p5-gray-dim);\">还没有战斗记录。</p>\n    </div>\n  </section>\n</template>\n\n<style scoped>\n.combat-panel {\n  position: relative;\n  display: grid;\n  gap: 12px;\n}\n\n.combat-effect-layer {\n  position: absolute;\n  inset: 64px 0 auto;\n  z-index: 4;\n  display: grid;\n  place-items: center;\n  pointer-events: none;\n}\n\n.combat-sprite-effect {\n  width: 128px;\n  height: 128px;\n  background-repeat: no-repeat;\n  background-size: 512px 128px;\n  background-position: 0 0;\n  animation: combat-sprite-sheet 520ms steps(4);\n}\n\n.combat-sprite-effect.effect-slash {\n  transform: scale(1.26) rotate(-8deg);\n  filter: drop-shadow(0 0 18px rgba(255, 255, 255, 0.3));\n}\n\n.combat-sprite-effect.effect-magic {\n  transform: scale(1.18);\n  filter: drop-shadow(0 0 22px rgba(80, 184, 255, 0.42));\n}\n\n.combat-sprite-effect.effect-heal {\n  transform: scale(1.14);\n  filter: drop-shadow(0 0 22px rgba(122, 255, 104, 0.38));\n}\n\n@keyframes combat-sprite-sheet {\n  from {\n    background-position: 0 0;\n  }\n  to {\n    background-position: -512px 0;\n  }\n}\n\n.victory-card {\n  display: grid;\n  gap: 8px;\n  padding: 8px 12px 12px;\n  overflow: hidden;\n  background: rgba(0, 204, 102, 0.06);\n  border-left: 4px solid var(--p5-safe);\n}\n\n.victory-banner {\n  display: block;\n  width: min(420px, 100%);\n  height: auto;\n  margin: -8px auto -4px;\n  object-fit: contain;\n  pointer-events: none;\n  filter: drop-shadow(0 0 14px rgba(245, 197, 66, 0.22));\n}\n</style>\n"],"sourceRoot":""}]);
