import type { GameSave, PlayerSkillState, ProfessionId, SkillId } from './types';

export type SkillSourceKind = 'initial' | 'hero_relic' | 'profession' | 'drop' | 'shop' | 'mentor' | 'quest';

export interface SkillDefinition {
  id: SkillId;
  name: string;
  sourceKind: SkillSourceKind;
  professionId?: ProfessionId;
  description: string;
  tags: string[];
}

export interface SkillLoadout {
  knownHeroSkills: SkillDefinition[];
  knownProfessionSkills: SkillDefinition[];
  loadout: SkillDefinition[];
  availableToLearn: SkillDefinition[];
}

