export function createInitialSkillState(): PlayerSkillState {
  return {
    knownHeroSkillIds: ['hero_strike', 'hero_guard'],
    knownProfessionSkillIds: [],
    loadoutSkillIds: ['hero_strike', 'hero_guard'],
  };
}

export function getSkillDefinition(skillId: SkillId): SkillDefinition {
  const skill = SKILL_DEFINITIONS.find(item => item.id === skillId);
  if (!skill) throw Error(`未知技能: ${skillId}`);
  return skill;
}

function uniqueSkillIds(skillIds: SkillId[]): SkillId[] {
  return Array.from(new Set(skillIds));
}

function resolveSkills(skillIds: SkillId[]): SkillDefinition[] {
  return uniqueSkillIds(skillIds)
    .map(skillId => SKILL_DEFINITIONS.find(skill => skill.id === skillId))
    .filter((skill): skill is SkillDefinition => Boolean(skill));
}

export function getSkillLoadout(save: GameSave): SkillLoadout {
  const player = save.playerState;
  if (!player) {
    return {
      knownHeroSkills: [],
      knownProfessionSkills: [],
      loadout: [],
      availableToLearn: [],
    };
  }

  const knownIds = new Set([...player.skills.knownHeroSkillIds, ...player.skills.knownProfessionSkillIds]);
  const activeProfession = player.professions.active;
  const availableToLearn = SKILL_DEFINITIONS.filter(skill => {
    if (knownIds.has(skill.id)) return false;
    if (skill.sourceKind === 'initial') return false;
    if (skill.sourceKind === 'profession') return skill.professionId === activeProfession;
    return skill.sourceKind === 'hero_relic';
  });

  return {
    knownHeroSkills: resolveSkills(player.skills.knownHeroSkillIds),
    knownProfessionSkills: resolveSkills(player.skills.knownProfessionSkillIds),
    loadout: resolveSkills(player.skills.loadoutSkillIds),
    availableToLearn,
  };
}

export function learnHeroSkill(save: GameSave, skillId: SkillId): GameSave {
  if (!save.playerState) throw Error('尚未创建玩家状态。');
  const skill = getSkillDefinition(skillId);
  if (skill.sourceKind !== 'hero_relic' && skill.sourceKind !== 'initial') throw Error('这不是勇者技能。');
  const knownHeroSkillIds = uniqueSkillIds([...save.playerState.skills.knownHeroSkillIds, skillId]);
  const loadoutSkillIds = uniqueSkillIds([...save.playerState.skills.loadoutSkillIds, skillId]).slice(0, 6);
  return {
    ...save,
    playerState: {
      ...save.playerState,
      skills: {
        ...save.playerState.skills,
        knownHeroSkillIds,
        loadoutSkillIds,
      },
    },
  };
}

export function learnProfessionSkill(save: GameSave, skillId: SkillId): GameSave {
  if (!save.playerState) throw Error('尚未创建玩家状态。');
  const skill = getSkillDefinition(skillId);
  if (skill.sourceKind !== 'profession' || !skill.professionId) throw Error('这不是职业技能。');
  if (skill.professionId !== save.playerState.professions.active) throw Error('只能学习当前职业路线的技能。');
  const knownProfessionSkillIds = uniqueSkillIds([...save.playerState.skills.knownProfessionSkillIds, skillId]);
  const loadoutSkillIds = uniqueSkillIds([...save.playerState.skills.loadoutSkillIds, skillId]).slice(0, 6);
  return {
    ...save,
    playerState: {
      ...save.playerState,
      skills: {
        ...save.playerState.skills,
        knownProfessionSkillIds,
        loadoutSkillIds,
      },
    },
  };
}
