import {
  GAME_CONTENT_VERSION,
  V1_0_CONTENT_PACK_ID,
  type ContentRuntimeState,
  type GameSave,
} from './types';

export const V1_0_CHAPTER_IDS = [
  'chapter_reality_opening',
  'chapter_aruma_border',
  'chapter_broken_frame_cave',
  'chapter_world_map_crossroads',
  'chapter_four_continent_gates',
  'chapter_demon_castle_approach',
] as const;

export function createInitialContentRuntimeState(): ContentRuntimeState {
  return {
    contentVersion: GAME_CONTENT_VERSION,
    enabledContentPackIds: [V1_0_CONTENT_PACK_ID],
    unlockedChapterIds: ['chapter_reality_opening'],
    completedChapterIds: [],
    migrationLog: [`${GAME_CONTENT_VERSION}: v1.0 四纹章巡礼版固定封包启用`],
    resetTokenLedger: {},
  };
}

function getUnlockedChapterIds(save: Partial<GameSave>, current: string[]): string[] {
  const completed = new Set(Object.values(save.quests?.records || {}).filter(record => record.status === 'completed').map(record => record.questId));
  const unlocked = new Set<string>(current.length ? current : ['chapter_reality_opening']);

  if (completed.has('mq_003_crossing') || save.stage === 'eight_bit_ready') unlocked.add('chapter_aruma_border');
  if (completed.has('mq_013_twin')) unlocked.add('chapter_broken_frame_cave');
  if (completed.has('mq_015_leim_name')) unlocked.add('chapter_world_map_crossroads');
  if (completed.has('mq_030_four_continents')) unlocked.add('chapter_four_continent_gates');
  if (completed.has('mq_060_frost_trial')) unlocked.add('chapter_demon_castle_approach');

  return Array.from(unlocked);
}

function getCompletedChapterIds(save: Partial<GameSave>, current: string[]): string[] {
  const completedQuests = new Set(Object.values(save.quests?.records || {}).filter(record => record.status === 'completed').map(record => record.questId));
  const completed = new Set(current);

  if (completedQuests.has('mq_003_crossing')) completed.add('chapter_reality_opening');
  if (completedQuests.has('mq_013_twin')) completed.add('chapter_aruma_border');
  if (completedQuests.has('mq_015_leim_name')) completed.add('chapter_broken_frame_cave');
  if (completedQuests.has('mq_030_four_continents')) completed.add('chapter_world_map_crossroads');
  if (
    completedQuests.has('mq_031_verdant_trial') &&
    completedQuests.has('mq_040_tide_trial') &&
    completedQuests.has('mq_050_ember_trial') &&
    completedQuests.has('mq_060_frost_trial')
  ) {
    completed.add('chapter_four_continent_gates');
  }
  if (completedQuests.has('mq_070_demon_castle_gate')) completed.add('chapter_demon_castle_approach');

  return Array.from(completed);
}

export function normalizeContentRuntimeState(raw: unknown, save: Partial<GameSave>): ContentRuntimeState {
  const fallback = createInitialContentRuntimeState();
  const candidate = raw && typeof raw === 'object' ? (raw as Partial<ContentRuntimeState>) : {};
  const enabledContentPackIds = Array.from(new Set([...(candidate.enabledContentPackIds || []), V1_0_CONTENT_PACK_ID]));
  const migrationLog = Array.from(
    new Set([
      ...(candidate.migrationLog || []),
      ...(candidate.contentVersion === GAME_CONTENT_VERSION ? [] : [`${GAME_CONTENT_VERSION}: 自动补齐 v1.0 内容包运行字段`]),
    ]),
  ).slice(-20);

  const normalized: ContentRuntimeState = {
    contentVersion: GAME_CONTENT_VERSION,
    enabledContentPackIds,
    unlockedChapterIds: candidate.unlockedChapterIds || fallback.unlockedChapterIds,
    completedChapterIds: candidate.completedChapterIds || fallback.completedChapterIds,
    migrationLog: migrationLog.length ? migrationLog : fallback.migrationLog,
    resetTokenLedger: candidate.resetTokenLedger || {},
  };

  return {
    ...normalized,
    unlockedChapterIds: getUnlockedChapterIds(save, normalized.unlockedChapterIds),
    completedChapterIds: getCompletedChapterIds(save, normalized.completedChapterIds),
  };
}
