const NARRATION_KIND_LABELS: Record<NarrationKind, string> = {
  scene: '场景描写',
  npc: 'NPC 对话',
  quest: '任务推进',
  combat: '战斗转写',
  free: '自由叙述',
};

export function createInitialNarrationState(): NarrationState {
  return {
    lastSituationSummary: '',
    entries: [],
    summary: createInitialStorySummaryState(),
  };
}

export function createInitialStorySummaryState(): StorySummaryState {
  return {
    current: '',
    count: 0,
    batches: [],
  };
}

function normalizeStorySummaryState(raw: unknown): StorySummaryState {
  const fallback = createInitialStorySummaryState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<StorySummaryState>;
  return {
    current: candidate.current || '',
    count: Number.isFinite(candidate.count) ? Number(candidate.count) : candidate.batches?.length || 0,
    lastGeneratedAtIso: candidate.lastGeneratedAtIso,
    lastError: candidate.lastError,
    batches: (candidate.batches || []).map((batch, index) => ({
      id: batch.id || createId('sum'),
      index: Number.isFinite(batch.index) ? batch.index : index + 1,
      entryIds: batch.entryIds || [],
      entryCount: Number.isFinite(batch.entryCount) ? batch.entryCount : batch.entryIds?.length || 0,
      createdAtIso: batch.createdAtIso || nowIso(),
      summaryText: batch.summaryText || '',
    })),
  };
}

export function normalizeNarrationState(raw: unknown): NarrationState {
  const fallback = createInitialNarrationState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<NarrationState>;
  return {
    lastSituationSummary: candidate.lastSituationSummary || '',
    lastGeneratedAtIso: candidate.lastGeneratedAtIso,
    lastError: candidate.lastError,
    entries: (candidate.entries || []).map(entry => ({
      ...entry,
      itemIds: entry.itemIds || [],
      npcIds: entry.npcIds || [],
      monsterIds: entry.monsterIds || [],
      characterTags: entry.characterTags || [],
    })),
    summary: normalizeStorySummaryState(candidate.summary),
  };
}

export function stripNarrationTimestamp(text: string): string {
  return text.replace(/\s*\[TIME:[^\]]+\]\s*$/i, '').trim();
}

export function getChronologicalNarrationEntries(save: GameSave): NarrationEntry[] {
  return [...save.narration.entries].reverse();
}

export function getUnsummarizedNarrationEntries(save: GameSave): NarrationEntry[] {
  return getChronologicalNarrationEntries(save).filter(entry => !entry.summaryBatchId);
}

export function getSummarizedNarrationEntries(save: GameSave): NarrationEntry[] {
  return getChronologicalNarrationEntries(save).filter(entry => Boolean(entry.summaryBatchId));
}

function formatInventoryLine(save: GameSave): string {
  const items = save.inventory.items
    .filter(item => item.count > 0)
    .slice(0, 8)
    .map(item => `${item.name} x${item.count}`);
  return items.length ? items.join('、') : '无显著物品';
}

function formatPlayerLine(save: GameSave): string {
  if (!save.playerState) return '尚未初始化';
  const identity = save.player
    ? `${save.player.username}（${PLAYER_GENDER_LABELS[save.player.gender]}）`
    : '{{user}}';
  return `${identity} / Lv.${save.playerState.level}，HP ${save.playerState.currentHp}，MP ${save.playerState.currentMp}`;
}

export function buildSituationSummary(save: GameSave): string {
  const location = getCurrentLocation(save);
  const clock = getClockDisplay(save.clock);
  const activeQuest = getActiveMainQuest(save);
  const visibleNpcs = getLocationNpcDefinitions(location.id);
  const recentTalks = save.npc.talkLog
    .slice(0, 4)
    .map(log => `${log.npcName}/${log.topicLabel}`)
    .join('、');
  const recentMessages = save.messages
    .slice(-4)
    .map(message => `${message.role}: ${message.text.slice(0, 80).replace(/\s+/g, ' ')}`)
    .join('\n');

  return [
    `设定时间：现实 ${clock.reality.label} / 8bit ${clock.eightBit.label} / 当前 ${clock.modeLabel}`,
    `现实状态：${getRealitySummary(save)}`,
    `项目：8bit的幻想`,
    `模式：${save.worldMode === 'reality' ? '现实世界' : '8bit世界'}`,
    `阶段：${save.stage}`,
    `地点：${location.name} / ${location.region}`,
    `地点说明：${location.description}`,
    `地图提示：${location.mapHint}`,
    `玩家：${formatPlayerLine(save)}`,
    `当前主线：${activeQuest?.definition.name || '无'} / ${getQuestHint(save)}`,
    `战斗状态：${getCombatSummary(save)}`,
    `背包摘要：${formatInventoryLine(save)}；金币 ${save.inventory.gold}`,
    `当前位置固定 NPC：${visibleNpcs.length ? visibleNpcs.map(npc => `${npc.name}（${npc.title}）`).join('、') : '无'}`,
    `最近 NPC 互动：${recentTalks || '无'}`,
    `最近消息：\n${recentMessages || '无'}`,
  ].join('\n');
}

function extractCharacterTags(save: GameSave, text: string): string[] {
  const location = getCurrentLocation(save);
  const visibleNpcs = getLocationNpcDefinitions(location.id);
  const knownNames = [
    ...visibleNpcs.flatMap(npc => [npc.name, npc.title]),
    '艾诺',
    '芬恩',
    '伊莉亚',
    '莉娅',
    '里昂',
    '罗罗',
    '诺玛',
    '布洛',
    '莱姆',
  ].filter(Boolean);
  const found = knownNames.filter(name => text.includes(name));
  const dialogueNames = Array.from(text.matchAll(/([\u4e00-\u9fa5A-Za-z0-9_]{1,12})说[:：]/g)).map(match => match[1]);
  return Array.from(new Set([...found, ...dialogueNames])).slice(0, 12);
}

function safeMonsterName(monsterId: string): string {
  try {
    return getMonster(monsterId).name;
  } catch {
    return monsterId;
  }
}

function formatOptionalList(values?: string[]): string {
  const list = (values || []).filter(Boolean);
  return list.length ? list.join('、') : '无';
}

function getEventNarrationKind(eventType: NarrativeEventPayload['eventType']): NarrationKind {
  if (eventType === 'npc_talk' || eventType === 'npc_contact' || eventType === 'npc_dialogue') return 'npc';
  if (eventType.startsWith('quest_')) return 'quest';
  if (eventType.startsWith('combat_')) return 'combat';
  if (eventType === 'item_gain' || eventType === 'item_use') return 'scene';
  return 'scene';
}

function buildQuestEventLine(event: NarrativeEventPayload): string {
  if (!event.questId) return '相关任务：无';
  const definition = getQuestDefinition(event.questId);
  if (!definition) return `相关任务：${event.questId}`;
  const objective = event.objectiveId ? definition.objectives.find(item => item.id === event.objectiveId) : undefined;
  return [
    `相关任务：${definition.name}（${definition.kind} / ${definition.chapter} / ${definition.id}）`,
    `任务摘要：${definition.summary}`,
    `任务叙事提示：${definition.aiSummary}`,
    objective ? `当前目标：${objective.label}` : '',
  ]
    .filter(Boolean)
    .join('\n');
}

function buildNpcEventLine(event: NarrativeEventPayload): string {
  if (!event.npcId) return '相关 NPC：无';
  const npc = getNpcDefinition(event.npcId);
  const name = event.npcName || npc?.name || event.npcId;
  const title = npc?.title ? `（${npc.title}）` : '';
  return [
    `相关 NPC：${name}${title} / ${event.npcId}`,
    npc?.description ? `NPC 简述：${npc.description}` : '',
    npc?.worldbookHint ? `NPC 世界书提示：${npc.worldbookHint}` : '',
    event.topicLabel ? `话题：${event.topicLabel}${event.topicId ? ` / ${event.topicId}` : ''}` : '',
    event.topicSeed ? `话题种子：${event.topicSeed}` : '',
  ]
    .filter(Boolean)
    .join('\n');
}

function buildItemEventLine(event: NarrativeEventPayload): string {
  const itemIds = event.itemIds || [];
  if (!itemIds.length && !event.itemSummary) return '相关物品：无';
  const items = itemIds.map(itemId => {
    const definition = getItemDefinition(itemId);
    return definition ? `${definition.name}（${definition.kind} / ${definition.itemId}）：${definition.description}` : itemId;
  });
  return [`相关物品：${items.join('；') || '无'}`, event.itemSummary ? `物品结果：${event.itemSummary}` : '']
    .filter(Boolean)
    .join('\n');
}

function buildMonsterEventLine(event: NarrativeEventPayload): string {
  const monsterIds = Array.from(new Set(event.monsterIds || []));
  if (!monsterIds.length && !event.combatSummary) return '相关怪物：无';
  return [
    `相关怪物：${monsterIds.map(monsterId => `${safeMonsterName(monsterId)} / ${monsterId}`).join('、') || '无'}`,
    event.combatSummary ? `战斗结果：${event.combatSummary}` : '',
    event.combatLog?.length ? `前端战斗日志：\n${event.combatLog.map(line => `- ${line}`).join('\n')}` : '',
  ]
    .filter(Boolean)
    .join('\n');
}

function buildLocationEventLine(save: GameSave, event: NarrativeEventPayload): string {
  const current = getCurrentLocation(save);
  const target = event.locationId ? getLocationDefinition(event.locationId) : current;
  const previous = event.previousLocationId ? getLocationDefinition(event.previousLocationId) : undefined;
  return [
    previous ? `出发地点：${previous.name} / ${previous.region} / ${previous.id}` : '',
    target ? `事件地点：${target.name} / ${target.region} / ${target.id}` : `事件地点：${current.name} / ${current.region} / ${current.id}`,
    target?.description ? `地点说明：${target.description}` : '',
    target?.mapHint ? `地点提示：${target.mapHint}` : '',
  ]
    .filter(Boolean)
    .join('\n');
}

function buildNarrativeEventPacket(save: GameSave, event: NarrativeEventPayload): string {
  const relatedFacts = event.extraFacts?.length ? event.extraFacts.map(fact => `- ${fact}`).join('\n') : '- 无';
  return [
    '```yaml',
    'frontend_narrative_event:',
    `  event_id: "${event.eventId || 'pending'}"`,
    `  event_type: "${event.eventType}"`,
    `  title: "${event.title.replaceAll('"', "'")}"`,
    `  player_intent: "${(event.playerIntent || event.title).replaceAll('"', "'")}"`,
    '  authority:',
    `    result: "${event.authoritativeResult.replaceAll('"', "'")}"`,
    `    quest_id: "${event.questId || ''}"`,
    `    objective_id: "${event.objectiveId || ''}"`,
    `    location_id: "${event.locationId || getCurrentLocation(save).id}"`,
    `    npc_id: "${event.npcId || ''}"`,
    `    topic_id: "${event.topicId || ''}"`,
    `    item_ids: [${(event.itemIds || []).map(itemId => `"${itemId}"`).join(', ')}]`,
    `    monster_ids: [${(event.monsterIds || []).map(monsterId => `"${monsterId}"`).join(', ')}]`,
    `    related_flags: [${(event.relatedFlags || []).map(flag => `"${flag}"`).join(', ')}]`,
    '```',
    '',
    buildLocationEventLine(save, event),
    buildQuestEventLine(event),
    buildNpcEventLine(event),
    buildItemEventLine(event),
    buildMonsterEventLine(event),
    `相关 flag：${formatOptionalList(event.relatedFlags)}`,
    `补充事实：\n${relatedFacts}`,
  ].join('\n');
}

function buildNarrativeEventPrompt(
  save: GameSave,
  event: NarrativeEventPayload,
  kind: NarrationKind,
  situationSummary?: string,
): string {
  const summary = situationSummary || buildSituationSummary(save);
  const phaseRule =
    event.eventType === 'quest_accept'
      ? '本次是任务接触阶段：把委托写成可继续交谈、可询问细节、可出发行动的剧情，不要把任务写成已经完成。'
      : event.eventType === 'quest_progress'
        ? '本次是任务推进阶段：承认前端已经记录的目标变化，用正文写调查、对话、发现或行动结果，并自然引出下一步。'
        : event.eventType === 'quest_turn_in'
          ? '本次是任务交付阶段：承认任务已经由前端完成结算，写交接、NPC 反应、后续影响和玩家能感受到的奖励事实。'
          : event.eventType === 'npc_contact'
            ? '本次是 NPC 接触阶段：写玩家靠近、NPC 注意到玩家、可交谈或可触发事项浮现的过程，不要把接触写成已经完成任务。'
            : event.eventType === 'npc_dialogue'
              ? '本次是 NPC 自由交谈阶段：围绕玩家原文写自然对白和动作反馈，可以让 NPC 追问或给出线索，但不能直接结算任务或奖励。'
              : event.eventType === 'npc_talk'
            ? '本次是 NPC 话题阶段：围绕玩家点选的话题写自然对白，允许玩家继续追问，不要把对话压缩成一句说明。'
            : event.eventType.startsWith('combat_')
              ? '本次是战斗正文阶段：只能把前端战斗日志和结算改写成正文，不新增伤害、胜负、掉落或敌人。'
              : '本次是前端事件正文阶段：把权威结果写进可读正文，让日志承认玩家刚刚做过的事。';

  return [
    '时间戳约定：末尾必须附一行 [TIME: reality +0m] 或 [TIME: eight_bit +0m]。需要推进时只能写相对分钟或小时；普通事件默认 +0m。',
    '你正在为互动游戏《8bit的幻想》把一个已由前端脚本结算的玩法事件写成 AIRP 正文日志。',
    `本次叙述类型：${NARRATION_KIND_LABELS[kind]}。`,
    phaseRule,
    '正文目标：让任务交接、物品获得、NPC 交谈、移动、战斗结果等关键前端操作都成为沉浸式历史，而不是只留在面板状态里。',
    '你只能写旁白、对白、气氛、NPC 反应、过程演绎和后续可选行动。所有经验、伤害、掉落、金币、装备、地图移动、任务完成由前端脚本权威结算。',
    '不得伪造未发生的奖励、未解锁地点、未获得物品、未完成任务或未出现的 NPC。不得擅自补完莱姆详细人设、最终决战或大结局。',
    '输出要求：中文正文，700 字以内；不要输出 YAML、JSON、接口说明或“前端已处理”这类破坏沉浸的字样；末尾附时间戳。',
    '',
    '权威局势摘要：',
    summary,
    '',
    '前端权威事件包：',
    buildNarrativeEventPacket(save, event),
  ].join('\n');
}

function buildEventWorldbookScanTags(save: GameSave, event?: NarrativeEventPayload): string[] {
  const location = getCurrentLocation(save);
  const activeQuest = getActiveMainQuest(save);
  const visibleNpcs = getLocationNpcDefinitions(location.id);
  const eventQuest = event?.questId ? getQuestDefinition(event.questId) : undefined;
  const eventLocation = event?.locationId ? getLocationDefinition(event.locationId) : undefined;
  const previousLocation = event?.previousLocationId ? getLocationDefinition(event.previousLocationId) : undefined;
  const tags = [
    '[8bit:runtime]',
    '[8bit:v1_0]',
    `[8bit:mode:${save.worldMode}]`,
    `[8bit:location:${location.id}]`,
    `v1_0_loc_${location.id}`,
    location.name,
    location.region,
    activeQuest ? `[8bit:quest:${activeQuest.definition.id}]` : '',
    activeQuest ? `v1_0_${activeQuest.definition.id}` : '',
    activeQuest?.definition.name || '',
    ...visibleNpcs.flatMap(npc => [`[8bit:npc:${npc.id}]`, npc.name, npc.title]),
    event ? `[8bit:event:${event.eventType}]` : '',
    eventQuest ? `[8bit:quest:${eventQuest.id}]` : '',
    eventQuest ? (eventQuest.kind === 'main' ? `v1_0_${eventQuest.id}` : `v1_0_side_${eventQuest.id}`) : '',
    eventQuest?.name || '',
    eventLocation ? `[8bit:location:${eventLocation.id}]` : '',
    eventLocation ? `v1_0_loc_${eventLocation.id}` : '',
    eventLocation?.name || '',
    previousLocation ? `[8bit:location:${previousLocation.id}]` : '',
    previousLocation ? `v1_0_loc_${previousLocation.id}` : '',
    ...(event?.npcId ? [`[8bit:npc:${event.npcId}]`, `v1_0_npc_${event.npcId}`, event.npcName || getNpcDefinition(event.npcId)?.name || ''] : []),
    ...(event?.itemIds || []).flatMap(itemId => {
      const item = getItemDefinition(itemId);
      return [`[8bit:item:${itemId}]`, `v1_0_item_${itemId}`, item?.name || ''];
    }),
    ...(event?.monsterIds || []).flatMap(monsterId => [`[8bit:monster:${monsterId}]`, `v1_0_monster_${monsterId}`, safeMonsterName(monsterId)]),
    ...(event?.relatedFlags || []).map(flag => `[8bit:flag:${flag}]`),
  ].filter(Boolean);
  return Array.from(new Set(tags));
}

export function buildNarrationWorldbookScanText(save: GameSave, userInput: string, kind: NarrationKind): string {
  const tags = [
    ...buildEventWorldbookScanTags(save),
    `[8bit:narration:${kind}]`,
  ].filter(Boolean);
  return [`[8bit:worldbook-scan]`, ...tags, userInput].join('\n');
}

export function buildNarrativeEventWorldbookScanText(
  save: GameSave,
  event: NarrativeEventPayload,
  userInput: string,
  kind: NarrationKind,
): string {
  const tags = [
    ...buildEventWorldbookScanTags(save, event),
    `[8bit:narration:${kind}]`,
  ].filter(Boolean);
  return [`[8bit:worldbook-scan]`, ...tags, userInput, event.authoritativeResult].join('\n');
}

export interface StoryHistoryPrompt {
  role: 'system' | 'assistant' | 'user';
  content: string;
}

export function buildStoryHistoryPrompts(save: GameSave): StoryHistoryPrompt[] {
  const prompts: StoryHistoryPrompt[] = [];
  const summary = save.narration.summary.current.trim();
  if (summary) {
    prompts.push({
      role: 'system',
      content: `<additional_settings>\n${summary}\n</additional_settings>`,
    });
  }

  getUnsummarizedNarrationEntries(save).forEach((entry, index) => {
    const number = index + 1;
    if (entry.userInput.trim()) {
      prompts.push({
        role: 'user',
        content: `[未总结日志 ${number} / 玩家行动]\n${entry.userInput.trim()}`,
      });
    }
    prompts.push({
      role: 'assistant',
      content: `[未总结日志 ${number} / 正文]\n<content>\n${stripNarrationTimestamp(entry.text)}\n</content>`,
    });
  });

  return prompts;
}

export function buildNarrationPrompt(save: GameSave, userInput: string, kind: NarrationKind, situationSummary?: string): string {
  const summary = situationSummary || buildSituationSummary(save);
  return [
    '时间戳约定：末尾必须附一行 [TIME: reality +0m] 或 [TIME: eight_bit +0m]。需要推进时只能写相对分钟或小时，例如 [TIME: reality +15m]、[TIME: eight_bit +2h]；普通回复不超过现实等价三小时，战斗中默认 +0m。',
    '你正在为互动游戏《8bit的幻想》生成主叙述。',
    `本次叙述类型：${NARRATION_KIND_LABELS[kind]}。`,
    '你只能写旁白、对白、气氛、NPC 反应和剧情补全。所有经验、伤害、掉落、金币、装备、地图移动、任务完成都由前端脚本结算。',
    '你不能直接修改变量、输出存档指令、伪造任务奖励，不能擅自补完莱姆详细人设、最终决战或大结局。',
    '如果需要推动玩法，请用自然语言提出可由玩家点击的下一步，而不是宣告权威结果。',
    '输出要求：中文正文，800 字以内。末尾附一行时间戳，格式为 [TIME: reality +0m] 或 [TIME: eight_bit +0m]，除非用户明确要求时间流逝，默认 +0m。',
    '',
    '权威局势摘要：',
    summary,
    '',
    '玩家本次意图：',
    userInput,
  ].join('\n');
}

export async function generateNarrationFromInput(
  save: GameSave,
  userInput: string,
  kind: NarrationKind = 'free',
): Promise<GameSave> {
  const trimmedInput = userInput.trim();
  if (!trimmedInput) throw Error('叙述输入不能为空。');

  const situationSummary = buildSituationSummary(save);
  const taskKind = kind === 'combat' ? 'combat_transcript' : 'main_narration';
  const text = await generateWithProfile(save.api, taskKind, {
    systemPrompt: buildNarrationPrompt(save, trimmedInput, kind, situationSummary),
    userInput: trimmedInput,
    historyPrompts: buildStoryHistoryPrompts(save),
    worldbookScanText: buildNarrationWorldbookScanText(save, trimmedInput, kind),
    maxChatHistory: 0,
  });
  const timestamp = nowIso();
  const location = getCurrentLocation(save);
  const cleanText = stripNarrationTimestamp(text);
  const entry: NarrationEntry = {
    id: createId('nar'),
    kind,
    userInput: trimmedInput,
    text,
    situationSummary,
    createdAtIso: timestamp,
    characterTags: extractCharacterTags(save, `${trimmedInput}\n${cleanText}`),
    locationName: location.name,
    modeLabel: save.worldMode === 'reality' ? '现实世界' : '8bit世界',
  };
  const nextSave: GameSave = {
    ...save,
    clock: applyAiTimestamp(save.clock, text, { combatActive: save.combat.active }),
    narration: {
      lastSituationSummary: situationSummary,
      lastGeneratedAtIso: timestamp,
      lastError: undefined,
      entries: [entry, ...save.narration.entries],
    },
  };
  return autoSummarizeStoryIfNeeded(recordMessage(recordMessage(nextSave, 'user', trimmedInput), 'assistant', text));
}

export async function generateNarrationFromEvent(save: GameSave, event: NarrativeEventPayload): Promise<GameSave> {
  const eventWithId: NarrativeEventPayload = {
    ...event,
    eventId: event.eventId || createId('evt'),
  };
  const kind = eventWithId.narrationKind || getEventNarrationKind(eventWithId.eventType);
  const userInput = (eventWithId.playerIntent || `前端事件：${eventWithId.title}`).trim();
  const situationSummary = buildSituationSummary(save);
  const taskKind = kind === 'combat' ? 'combat_transcript' : 'main_narration';
  const text = await generateWithProfile(save.api, taskKind, {
    systemPrompt: buildNarrativeEventPrompt(save, eventWithId, kind, situationSummary),
    userInput,
    historyPrompts: buildStoryHistoryPrompts(save),
    worldbookScanText: buildNarrativeEventWorldbookScanText(save, eventWithId, userInput, kind),
    maxChatHistory: 0,
  });
  const timestamp = nowIso();
  const location = eventWithId.locationId ? getLocationDefinition(eventWithId.locationId) || getCurrentLocation(save) : getCurrentLocation(save);
  const cleanText = stripNarrationTimestamp(text);
  const eventNpcName = eventWithId.npcName || (eventWithId.npcId ? getNpcDefinition(eventWithId.npcId)?.name : undefined);
  const entry: NarrationEntry = {
    id: createId('nar'),
    kind,
    userInput,
    text,
    situationSummary,
    createdAtIso: timestamp,
    sourceEventId: eventWithId.eventId,
    sourceEventType: eventWithId.eventType,
    questId: eventWithId.questId,
    itemIds: eventWithId.itemIds || [],
    npcIds: eventWithId.npcId ? [eventWithId.npcId] : [],
    monsterIds: eventWithId.monsterIds || [],
    characterTags: Array.from(
      new Set([...(eventNpcName ? [eventNpcName] : []), ...extractCharacterTags(save, `${userInput}\n${cleanText}`)]),
    ).slice(0, 12),
    locationName: location.name,
    modeLabel: save.worldMode === 'reality' ? '现实世界' : '8bit世界',
  };
  const nextSave: GameSave = {
    ...save,
    clock: applyAiTimestamp(save.clock, text, { combatActive: save.combat.active }),
    narration: {
      ...save.narration,
      lastSituationSummary: situationSummary,
      lastGeneratedAtIso: timestamp,
      lastError: undefined,
      entries: [entry, ...save.narration.entries],
    },
  };
  return autoSummarizeStoryIfNeeded(recordMessage(recordMessage(nextSave, 'user', userInput), 'assistant', text));
}

function buildSummaryInput(save: GameSave, entries: NarrationEntry[]): string {
  const previousSummary = save.narration.summary.current.trim() || '无';
  const logs = entries
    .map((entry, index) =>
      [
        `## 日志 ${index + 1}`,
        `- 记录ID: ${entry.id}`,
        `- 时间: ${entry.createdAtIso}`,
        `- 类型: ${NARRATION_KIND_LABELS[entry.kind]}`,
        `- 地点: ${entry.locationName || '未记录'}`,
        `- 模式: ${entry.modeLabel || '未记录'}`,
        `- 玩家行动: ${entry.userInput || '无'}`,
        `- 正文:`,
        stripNarrationTimestamp(entry.text),
      ].join('\n'),
    )
    .join('\n\n');

  return [
    '<additional_settings>',
    '## 之前的大总结',
    previousSummary,
    '',
    '## 新增日志',
    logs || '无',
    '</additional_settings>',
  ].join('\n');
}

