/** 圆形小地图默认数据（占位）。未来由正文输出 [MAP]...[/MAP] 解析填充 */
export interface MiniMapNode {
  type: 'player' | 'npc' | 'path';
  name: string;
  x: number; // 0-10 grid
  y: number;
}

export interface MiniMapLine {
  from: { x: number; y: number };
  to: { x: number; y: number };
}

export interface MiniMapData {
  nodes: MiniMapNode[];
  lines: MiniMapLine[];
}

