/**
 * 正文地图输出格式说明（占位文档）
 *
 * 正文在每轮回复末尾可以输出地图数据，格式如下：
 *
 * [MAP]
 * @:5,5              ← 玩家位置
 * N:村长的家:3,2      ← NPC 点
 * N:商店:7,4
 * P:北边小径:5,1      ← 路径点
 * L:5,1-5,5           ← 连线
 * [/MAP]
 *
 * 前端会在正文回复中用正则提取 [MAP]...[/MAP] 块并解析。
 * 解析后的数据会更新圆形小地图的显示。
 *
 * 未来实现：在 narration.ts 的 generateNarrationFromInput 中解析正文回复，
 * 提取地图数据并写入存档。
 */
export function parseMapBlock(text: string): MiniMapData | null {
  const match = text.match(/\[MAP\]([\s\S]*?)\[\/MAP\]/i);
  if (!match) return null;

  const lines = match[1].trim().split('\n').map(l => l.trim()).filter(Boolean);
  const nodes: MiniMapNode[] = [];
  const mapLines: MiniMapLine[] = [];

  for (const line of lines) {
    if (line.startsWith('@:')) {
      const [x, y] = line.slice(2).split(',').map(Number);
      if (Number.isFinite(x) && Number.isFinite(y)) {
        nodes.push({ type: 'player', name: '当前位置', x, y });
      }
    } else if (line.startsWith('N:')) {
      const parts = line.slice(2).split(':');
      if (parts.length >= 2) {
        const name = parts[0];
        const [x, y] = parts[1].split(',').map(Number);
        if (Number.isFinite(x) && Number.isFinite(y)) {
          nodes.push({ type: 'npc', name, x, y });
        }
      }
    } else if (line.startsWith('P:')) {
      const parts = line.slice(2).split(':');
      if (parts.length >= 2) {
        const name = parts[0];
        const [x, y] = parts[1].split(',').map(Number);
        if (Number.isFinite(x) && Number.isFinite(y)) {
          nodes.push({ type: 'path', name, x, y });
        }
      }
    } else if (line.startsWith('L:')) {
      const coords = line.slice(2).split('-');
      if (coords.length === 2) {
        const [x1, y1] = coords[0].split(',').map(Number);
        const [x2, y2] = coords[1].split(',').map(Number);
        if ([x1, y1, x2, y2].every(Number.isFinite)) {
          mapLines.push({ from: { x: x1, y: y1 }, to: { x: x2, y: y2 } });
        }
      }
    }
  }

  return nodes.length > 0 ? { nodes, lines: mapLines } : null;
}
