export type GameAction =
  | { type: 'CHARACTER_CREATE'; profile: CharacterCreationInput }
  | { type: 'OPENING_GENERATED'; text: string }
  | { type: 'MODE_SWITCH'; mode: WorldMode }
  | { type: 'WATCH_OPEN'; panel: WatchPanelId }
  | { type: 'TIME_SYNC_FROM_NARRATION'; rawText: string; sourceMessageId?: string; source?: 'ai' | 'manual' }
  | { type: 'TIME_ADVANCE_EVENT'; targetMode: StoryClockKind; deltaMinutes: number; reason: string }
  | { type: 'RESTORE_WORLDBOOK' }
  | { type: 'WATCH_LOCK_AND_CROSS' }
  | { type: 'PLAYER_GAIN_EXPERIENCE'; amount: number; source?: ExperienceSource }
  | { type: 'PLAYER_HEAL'; amount: number }
  | { type: 'PROFESSION_CHANGE'; professionId: ProfessionId }
  | { type: 'PROFESSION_POINT_GAIN'; points: Partial<ProfessionPointBlock>; label?: string }
  | { type: 'PROFESSION_FLAG_GAIN'; flag: string }
  | { type: 'PROFESSION_RESET'; methodId?: string }
  | { type: 'SKILL_LEARN'; skillId: SkillId }
  | { type: 'MAP_TRAVEL'; locationId: string }
  | { type: 'MAP_GRID_IMPORT'; locationId: string; rawGrid: string; source?: MiniMapGridSource }
  | { type: 'COMBAT_START_RANDOM'; locationId?: string }
  | { type: 'COMBAT_COMMAND'; command: CombatCommand }
  | { type: 'INVENTORY_USE_ITEM'; itemId: string }
  | { type: 'INVENTORY_ADD_ITEM'; itemId: string; count?: number }
  | { type: 'EQUIPMENT_EQUIP'; itemId: string; slot?: EquipmentSlot }
  | { type: 'EQUIPMENT_UNEQUIP'; slot: EquipmentSlot }
  | { type: 'QUEST_ACCEPT'; questId: string }
  | { type: 'QUEST_TURN_IN'; questId: string }
  | { type: 'QUEST_PROGRESS'; event: QuestEventInput }
  | { type: 'QUEST_SYNC'; kind?: QuestEventKind }
  | { type: 'REALITY_TRAVEL'; locationId: string }
  | { type: 'REALITY_ACTION'; actionId: string }
  | { type: 'REALITY_RECORD_CLUE'; clueId: string; source?: string }
  | { type: 'NPC_CONTACT'; npcId: string }
  | { type: 'NPC_DIALOGUE'; npcId: string; input: string }
  | { type: 'NPC_TALK'; npcId: string; topicId?: string }
  | { type: 'NPC_GENERATE_SCENE_DRAFT'; locationId?: string }
  | { type: 'WORLDBOOK_DRAFT_CONFIRM'; draftId: string }
  | { type: 'WORLDBOOK_DRAFT_REJECT'; draftId: string }
  | { type: 'NARRATION_GENERATE'; input: string; kind?: NarrationKind }
  | { type: 'STORY_SUMMARY_GENERATE' }
  | { type: 'ACHIEVEMENT_SYNC' }
  | { type: 'ACHIEVEMENT_GENERATE_DRAFT' }
  | { type: 'ACHIEVEMENT_CONFIRM'; draftId: string }
  | { type: 'ACHIEVEMENT_REJECT'; draftId: string };

function success(save: GameSave, message?: string): ActionResult {
  return { ok: true, save: syncStaticAchievements(save), message };
}

function failure(save: GameSave, error: unknown): ActionResult {
  const nextSave = recordDebugError(save, error);
  return { ok: false, save: nextSave, error: error instanceof Error ? error.message : String(error) };
}

function rejected(save: GameSave, message: string): ActionResult {
  return { ok: false, save: recordDebugError(save, message), error: message };
}

function clampPlayerVitalsToStats(save: GameSave): GameSave {
  if (!save.playerState) return save;
  const stats = getPlayerStats(save);
  if (!stats) return save;
  return {
    ...save,
    playerState: {
      ...save.playerState,
      currentHp: Math.min(save.playerState.currentHp, stats.derived.maxHp),
      currentMp: Math.min(save.playerState.currentMp, stats.derived.maxMp),
    },
  };
}

function applyQuestRewards(save: GameSave, definition: QuestDefinition): GameSave {
  const rewards = definition.rewards;
  let nextSave = save;

  (rewards.unlockLocationIds || []).forEach(locationId => {
    nextSave = unlockLocation(nextSave, locationId);
  });

  if (rewards.anchorLocationId) {
    nextSave = {
      ...nextSave,
      watch: {
        ...nextSave.watch,
        anchorLocationId: rewards.anchorLocationId,
      },
    };
  }

  if (rewards.gold || rewards.items?.length) {
    nextSave = addInventoryRewards(nextSave, rewards.gold || 0, rewards.items || [], `任务完成: ${definition.name}`);
  }

  if (rewards.professionPoints) {
    nextSave = grantProfessionPoints(nextSave, rewards.professionPoints);
  }

  (rewards.professionFlags || []).forEach(flag => {
    nextSave = grantProfessionFlag(nextSave, flag);
  });

  if (rewards.experience) {
    nextSave = addExperience(nextSave, rewards.experience, {
      kind: 'quest',
      id: definition.id,
      label: definition.name,
    }).save;
  }

  return refreshQuestState(nextSave);
}

function getErrorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function markNarrationFailure(save: GameSave, error: unknown): GameSave {
  const text = getErrorText(error);
  return recordDebugError(
    {
      ...save,
      narration: {
        ...save.narration,
        lastError: `正文生成失败：${text}`,
      },
    },
    `正文生成失败：${text}`,
  );
}

async function attachNarrativeEvent(
  save: GameSave,
  event: NarrativeEventPayload,
): Promise<{ save: GameSave; notice: string }> {
  try {
    return {
      save: await generateNarrationFromEvent(save, event),
      notice: '正文已写入日志。',
    };
  } catch (error) {
    return {
      save: markNarrationFailure(save, error),
      notice: `正文生成失败，可稍后在叙述栏补写：${getErrorText(error)}`,
    };
  }
}

function getChangedQuestIds(before: GameSave, after: GameSave): string[] {
  const ids = new Set([...Object.keys(before.quests.records), ...Object.keys(after.quests.records)]);
  return Array.from(ids).filter(questId => {
    const left = before.quests.records[questId];
    const right = after.quests.records[questId];
    return JSON.stringify(left || null) !== JSON.stringify(right || null);
  });
}

function getQuestObjectiveIdForEvent(definition: QuestDefinition | undefined, event: QuestEventInput): string | undefined {
  if (!definition) return undefined;
  const objective = definition.objectives.find(item => {
    if (item.kind === 'event' && event.kind === 'event') return item.targetId === event.targetId;
    if (item.kind === 'talk' && event.kind === 'talk') return item.targetId === event.npcId;
    if (item.kind === 'anchor' && event.kind === 'anchor_set') return item.targetId === event.locationId;
    if (item.kind === 'travel' && event.kind === 'travel') return item.targetId === event.locationId;
    if (item.kind === 'combat' && event.kind === 'combat_victory') {
      return !item.targetId || item.targetId === 'any' || (event.monsterIds || []).includes(item.targetId);
    }
    return false;
  });
  return objective?.id;
}

function formatQuestRewardSummary(definition: QuestDefinition): string {
  const rewards = definition.rewards;
  const parts: string[] = [];
  if (rewards.rewardCategoryIds?.length) parts.push(`奖励类别 ${rewards.rewardCategoryIds.join('、')}`);
  if (rewards.poolRewardHint) parts.push(`奖励池 ${rewards.poolRewardHint}`);
  if (rewards.items?.length) parts.push(`物品 ${rewards.items.map(item => `${item.name} x${item.count}`).join('、')}`);
  if (rewards.gold) parts.push(`金币 ${rewards.gold}`);
  if (rewards.experience) parts.push(`经验 ${rewards.experience}`);
  if (rewards.professionPoints) {
    const points = Object.entries(rewards.professionPoints)
      .filter(([, value]) => value)
      .map(([key, value]) => `${key}+${value}`)
      .join('、');
    if (points) parts.push(`职业点 ${points}`);
  }
  if (rewards.unlockLocationIds?.length) parts.push(`解锁地点 ${rewards.unlockLocationIds.join('、')}`);
  if (rewards.anchorLocationId) parts.push(`锚点 ${rewards.anchorLocationId}`);
  return parts.join('；') || '剧情推进';
}

function formatLocationName(locationId?: string): string {
  if (!locationId) return '当前位置';
  const location = getLocationDefinition(locationId);
  return location ? `${location.name}（${location.id}）` : locationId;
}

function formatItemName(itemId: string): string {
  const definition = getItemDefinition(itemId);
  return definition ? `${definition.name}（${definition.itemId}）` : itemId;
}

function shouldAutoNarrateItemGain(itemId: string): boolean {
  const definition = getItemDefinition(itemId);
  return definition?.kind === 'key' || definition?.kind === 'quest';
}

function getCombatMonsterIds(save: GameSave): string[] {
  return Array.from(new Set(save.combat.actors.flatMap(actor => (actor.monsterId ? [actor.monsterId] : []))));
}

function getRecentCombatLog(save: GameSave): string[] {
  return save.combat.log
    .slice(0, 12)
    .reverse()
    .map(log => log.text);
}

export async function dispatchGameAction(save: GameSave, action: GameAction): Promise<ActionResult> {
  try {
    const actionSave: GameSave = {
      ...save,
      debug: {
        ...save.debug,
        lastAction: action.type,
      },
    };

    switch (action.type) {
      case 'CHARACTER_CREATE': {
        const username = action.profile.username.trim().replace(/\s+/g, ' ');
        const profileText = action.profile.profileText.trim();
        const gender = action.profile.gender;
        if (!username) return failure(actionSave, '用户名不能为空。');
        if (gender !== 'male' && gender !== 'female') return failure(actionSave, '性别必须选择男或女。');
        if (!profileText) return failure(actionSave, '详细人设不能为空。');

        const player = {
          id: 'player' as const,
          username,
          gender,
          profileText,
          createdAtIso: nowIso(),
        };

        const profileSave: GameSave = {
          ...actionSave,
          stage: 'profile_created',
          player,
          playerState: createInitialPlayerState(),
          opening: {
            status: 'ready_for_ai',
            text: '用户名、性别和详细人设已经写入当前存档世界书。下一步可以请求正文生成最合适的开场白。',
          },
        };
        const { save: worldbookSave, entry } = await writePlayerProfileToWorldbook(profileSave, player);
        const nextSave = recordMessage(
          {
            ...worldbookSave,
            player: {
              ...player,
              worldbookEntryUid: entry?.uid,
              worldbookEntryName: entry?.name,
            },
          },
          'user',
          [`用户名：${username}`, `性别：${PLAYER_GENDER_LABELS[gender]}`, '详细人设：', profileText].join('\n'),
        );
        return success(applyQuestEvent(nextSave, { kind: 'profile_created' }), '现实身份已按 YAML 写入世界书。');
      }

      case 'OPENING_GENERATED':
        return success(
          applyQuestEvent(recordMessage(
            syncRealityFromEvent({
              ...actionSave,
              stage: 'opening_drafted',
              opening: {
                status: 'drafted',
                text: action.text,
                generatedAtIso: nowIso(),
              },
            }, 'opening_generated'),
            'assistant',
            action.text,
          ), { kind: 'opening_generated' }),
        );

      case 'MODE_SWITCH':
        if (actionSave.combat.active && action.mode === 'reality') {
          return failure(actionSave, '战斗中不能返回现实世界。');
        }
        if (action.mode === 'eight_bit' && actionSave.stage !== 'eight_bit_ready') {
          return failure(actionSave, '需要先锁定 8 bit。');
        }
        {
          const switchedSave = transformPlayerPresentation({
          ...actionSave,
          worldMode: action.mode,
          clock: switchClockMode(actionSave.clock, action.mode),
        }, action.mode);
          return success(action.mode === 'reality' ? syncRealityFromEvent(switchedSave, 'return_reality') : switchedSave);
        }

      case 'WATCH_OPEN':
        return success(setActiveWatchPanel(actionSave, action.panel));

      case 'TIME_SYNC_FROM_NARRATION':
      {
        const result = syncStoryTimeFromText(actionSave.clock, action.rawText, {
          source: action.source || 'manual',
          reason: action.source === 'ai' ? '正文叙述时间戳' : '手动同步时间戳',
          sourceMessageId: action.sourceMessageId,
          combatActive: actionSave.combat.active,
        });
        const nextSave = {
          ...actionSave,
          clock: result.clock,
        };
        return result.status === 'rejected' ? rejected(nextSave, result.message) : success(nextSave, result.message);
      }

      case 'TIME_ADVANCE_EVENT':
      {
        const result = advanceStoryTimeByEvent(actionSave.clock, action.targetMode, action.deltaMinutes, action.reason);
        const nextSave = {
          ...actionSave,
          clock: result.clock,
        };
        return result.status === 'rejected' ? rejected(nextSave, result.message) : success(nextSave, result.message);
      }

      case 'RESTORE_WORLDBOOK':
        return success(await restoreWorldbookForSave(actionSave), '当前存档世界书已恢复绑定。');

      case 'WATCH_LOCK_AND_CROSS':
        if (actionSave.opening.status !== 'drafted') return failure(actionSave, '需要先生成开场白。');
      {
        const crossedSave = applyQuestEvent(
          applyQuestEvent(
            transformPlayerPresentation(
              {
                ...syncRealityFromEvent(actionSave, 'watch_locked'),
                stage: 'eight_bit_ready',
                worldMode: 'eight_bit',
                clock: switchClockMode(actionSave.clock, 'eight_bit'),
                map: {
                  ...actionSave.map,
                  currentLocationId: 'initial_grassland',
                  visitedLocationIds: Array.from(new Set([...actionSave.map.visitedLocationIds, 'initial_grassland'])),
                },
              },
              'eight_bit',
            ),
            { kind: 'watch_locked' },
          ),
          { kind: 'travel', locationId: 'initial_grassland' },
        );
        const narrated = await attachNarrativeEvent(crossedSave, {
          eventType: 'watch_cross',
          narrationKind: 'scene',
          title: '锁定 8 bit 并进入初始草地',
          playerIntent: '锁定 8 bit，穿过手表进入初始草地。',
          authoritativeResult: '前端已切换到 8bit 世界，当前位置已经设为 initial_grassland，并推进手表锁定与移动任务事件。',
          locationId: 'initial_grassland',
          previousLocationId: actionSave.map.currentLocationId,
          extraFacts: ['开场白已生成。', '`8 bit` 手表成为现实与 8bit 世界之间的唯一超现实接口。'],
        });
        return success(narrated.save, `8 bit 已锁定。${narrated.notice}`);
      }

      case 'PLAYER_GAIN_EXPERIENCE': {
        const result = addExperience(actionSave, action.amount, action.source);
        return success(recordMessage(result.save, 'system', result.message), result.message);
      }

      case 'PLAYER_HEAL':
        return success(healPlayer(actionSave, action.amount), 'HP 已恢复。');

      case 'PROFESSION_CHANGE': {
        const stats = getPlayerStats(actionSave);
        const nextSave = changeProfession(actionSave, action.professionId, stats?.effectiveAttributes);
        return success(nextSave, '职业路线已切换。');
      }

      case 'PROFESSION_POINT_GAIN':
        return success(grantProfessionPoints(actionSave, action.points), action.label || '职业点数已记录。');

      case 'PROFESSION_FLAG_GAIN':
        return success(grantProfessionFlag(actionSave, action.flag), '职业条件已记录。');

      case 'PROFESSION_RESET':
        return success(resetProfessionPoints(actionSave), '职业路线已洗回勇者。');

      case 'SKILL_LEARN': {
        const skillId = action.skillId;
        const nextSave = skillId.startsWith('hero_') ? learnHeroSkill(actionSave, skillId) : learnProfessionSkill(actionSave, skillId);
        return success(nextSave, '技能已学习。');
      }

      case 'MAP_TRAVEL':
        if (actionSave.combat.active) return failure(actionSave, '战斗中不能移动地图。');
        if (actionSave.worldMode !== 'eight_bit' && action.locationId !== 'reality_origin') {
          return failure(actionSave, '需要进入 8bit 世界后才能移动 8bit 地图。');
        }
      {
        const previousLocationId = actionSave.map.currentLocationId;
        const traveledSave = applyQuestEvent(travelToLocation(actionSave, action.locationId), {
          kind: 'travel',
          locationId: action.locationId,
        });
        const narrated = await attachNarrativeEvent(traveledSave, {
          eventType: 'map_travel',
          narrationKind: 'scene',
          title: `前往${formatLocationName(action.locationId)}`,
          playerIntent: `从${formatLocationName(previousLocationId)}前往${formatLocationName(action.locationId)}。`,
          authoritativeResult: '前端已确认地图移动成功，并同步了相关旅行任务目标。',
          previousLocationId,
          locationId: action.locationId,
        });
        return success(narrated.save, `已经移动到新地点。${narrated.notice}`);
      }

      case 'MAP_GRID_IMPORT':
        return success(
          updateLocationMiniMapFromGrid(actionSave, action.locationId, action.rawGrid, action.source || 'api_generated'),
          '地图网格已解析并写入当前存档。',
        );

      case 'COMBAT_START_RANDOM': {
        const nextSave = startRandomEncounter(actionSave, action.locationId || actionSave.map.currentLocationId);
        const monsterIds = getCombatMonsterIds(nextSave);
        const narrated = await attachNarrativeEvent(nextSave, {
          eventType: 'combat_start',
          narrationKind: 'combat',
          title: '遭遇战开始',
          playerIntent: `在${formatLocationName(nextSave.combat.locationId || nextSave.map.currentLocationId)}遭遇敌人。`,
          authoritativeResult: '前端已经建立战斗状态，并等待玩家按战斗规则行动。',
          locationId: nextSave.combat.locationId || nextSave.map.currentLocationId,
          monsterIds,
          combatSummary: getCombatSummary(nextSave),
          combatLog: getRecentCombatLog(nextSave),
        });
        return success(narrated.save, `${getCombatSummary(narrated.save)}${narrated.notice}`);
      }

      case 'COMBAT_COMMAND': {
        const nextSave = submitCombatCommand(actionSave, action.command);
        const rewards = nextSave.combat.phase === 'victory' ? nextSave.combat.lastRewards : undefined;
        const questSave = rewards
          ? applyQuestEvent(nextSave, {
              kind: 'combat_victory',
              locationId: nextSave.combat.locationId,
              monsterIds: rewards.monsterIds,
            })
          : nextSave;
        if (['victory', 'defeat', 'escaped'].includes(questSave.combat.phase)) {
          const eventType =
            questSave.combat.phase === 'victory'
              ? 'combat_victory'
              : questSave.combat.phase === 'defeat'
                ? 'combat_defeat'
                : 'combat_escape';
          const narrated = await attachNarrativeEvent(questSave, {
            eventType,
            narrationKind: 'combat',
            title: getCombatSummary(questSave),
            playerIntent: '根据前端战斗结果记录本场战斗正文。',
            authoritativeResult: getCombatSummary(questSave),
            locationId: questSave.combat.locationId || questSave.map.currentLocationId,
            monsterIds: rewards?.monsterIds || getCombatMonsterIds(questSave),
            itemIds: rewards?.drops.map(drop => drop.itemId) || [],
            itemSummary: rewards?.drops.length
              ? `战斗掉落：${rewards.drops.map(drop => `${drop.name} x${drop.count}`).join('、')}`
              : '本场战斗没有显著掉落。',
            combatSummary: questSave.combat.transcriptSeed || getCombatSummary(questSave),
            combatLog: getRecentCombatLog(questSave),
          });
          return success(narrated.save, `${getCombatSummary(narrated.save)}${narrated.notice}`);
        }
        return success(questSave, getCombatSummary(questSave));
      }

      case 'INVENTORY_USE_ITEM': {
        const result = useInventoryItem(actionSave, action.itemId);
        const itemSave = refreshQuestState(recordMessage(result.save, 'system', result.message));
        const narrated = await attachNarrativeEvent(itemSave, {
          eventType: 'item_use',
          narrationKind: 'scene',
          title: `使用${formatItemName(action.itemId)}`,
          playerIntent: `使用${formatItemName(action.itemId)}。`,
          authoritativeResult: result.message,
          locationId: itemSave.map.currentLocationId,
          itemIds: [action.itemId],
        });
        return success(narrated.save, `${result.message}${narrated.notice}`);
      }

      case 'INVENTORY_ADD_ITEM':
      {
        const itemSave = refreshQuestState(addInventoryItem(actionSave, action.itemId, action.count || 1));
        if (!shouldAutoNarrateItemGain(action.itemId)) return success(itemSave, '物品已加入背包。');
        const narrated = await attachNarrativeEvent(itemSave, {
          eventType: 'item_gain',
          narrationKind: 'scene',
          title: `获得${formatItemName(action.itemId)}`,
          playerIntent: `获得${formatItemName(action.itemId)}。`,
          authoritativeResult: `前端已把 ${formatItemName(action.itemId)} x${action.count || 1} 加入背包。`,
          locationId: itemSave.map.currentLocationId,
          itemIds: [action.itemId],
          itemSummary: `${formatItemName(action.itemId)} x${action.count || 1}`,
        });
        return success(narrated.save, `物品已加入背包。${narrated.notice}`);
      }

      case 'EQUIPMENT_EQUIP':
        return success(refreshQuestState(clampPlayerVitalsToStats(equipInventoryItem(actionSave, action.itemId, action.slot))), '装备已穿戴。');

      case 'EQUIPMENT_UNEQUIP':
        return success(refreshQuestState(clampPlayerVitalsToStats(unequipInventorySlot(actionSave, action.slot))), '装备已卸下。');

      case 'QUEST_ACCEPT':
      {
        const definition = getQuestDefinition(action.questId);
        const questSave = acceptQuest(actionSave, action.questId);
        const narrated = await attachNarrativeEvent(questSave, {
          eventType: 'quest_accept',
          narrationKind: 'quest',
          title: `接取任务${definition ? `《${definition.name}》` : action.questId}`,
          playerIntent: `听取并接下任务${definition ? `《${definition.name}》` : action.questId}。`,
          authoritativeResult: '前端已把任务状态设为 active；任务尚未完成，后续过程需要通过正文与前端目标继续推进。',
          questId: action.questId,
          locationId: definition?.locationId || questSave.map.currentLocationId,
          npcName: definition?.giver,
          extraFacts: [
            definition?.giver ? `委托来源：${definition.giver}` : '委托来源未指定。',
            `任务奖励提示：${definition ? formatQuestRewardSummary(definition) : '未知'}`,
          ],
        });
        return success(narrated.save, `任务已接取。${narrated.notice}`);
      }

      case 'QUEST_PROGRESS': {
        const eventSave = action.event.kind === 'anchor_set' && action.event.locationId
          ? {
              ...actionSave,
              watch: {
                ...actionSave.watch,
                anchorLocationId: action.event.locationId,
              },
            }
          : actionSave;
        const progressedSave = applyQuestEvent(eventSave, action.event);
        const changedQuestIds = getChangedQuestIds(actionSave, progressedSave);
        if (!changedQuestIds.length) return success(progressedSave, '任务进度已记录。');
        const questId = changedQuestIds[0];
        const definition = getQuestDefinition(questId);
        const narrated = await attachNarrativeEvent(progressedSave, {
          eventType: 'quest_progress',
          narrationKind: 'quest',
          title: `推进任务${definition ? `《${definition.name}》` : questId}`,
          playerIntent: `记录任务进展：${definition?.name || questId}。`,
          authoritativeResult: '前端已根据事件更新任务目标状态；正文只能承认这次进展，不能额外完成其他目标。',
          questId,
          objectiveId: getQuestObjectiveIdForEvent(definition, action.event),
          locationId: action.event.locationId || progressedSave.map.currentLocationId,
          npcId: action.event.npcId,
          monsterIds: action.event.monsterIds,
          extraFacts: changedQuestIds.map(id => {
            const changed = getQuestDefinition(id);
            return `本次发生变化的任务：${changed?.name || id}`;
          }),
        });
        return success(narrated.save, `任务进度已记录。${narrated.notice}`);
      }

      case 'QUEST_TURN_IN': {
        const result = turnInQuest(actionSave, action.questId);
        const rewarded = applyQuestRewards(result.save, result.definition);
        const completedSave = recordMessage(rewarded, 'system', `任务完成：${result.definition.name}`);
        const narrated = await attachNarrativeEvent(completedSave, {
          eventType: 'quest_turn_in',
          narrationKind: 'quest',
          title: `交付任务《${result.definition.name}》`,
          playerIntent: `交付并完成任务《${result.definition.name}》。`,
          authoritativeResult: `前端已把任务设为 completed，并应用奖励：${formatQuestRewardSummary(result.definition)}。`,
          questId: result.definition.id,
          locationId: result.definition.locationId || completedSave.map.currentLocationId,
          npcName: result.definition.giver,
          itemIds: result.definition.rewards.items?.map(item => item.itemId) || [],
          itemSummary: formatQuestRewardSummary(result.definition),
          relatedFlags: result.definition.rewards.flags,
        });
        return success(narrated.save, `任务完成：${result.definition.name}。${narrated.notice}`);
      }

      case 'QUEST_SYNC':
        return success(applyQuestEvent(actionSave, { kind: action.kind || 'sync' }), '任务状态已同步。');

      case 'REALITY_TRAVEL': {
        const previousLocationId = actionSave.reality.currentLocationId;
        const result = travelRealityLocation(actionSave, action.locationId);
        const realitySave = recordMessage(result.save, 'system', result.message);
        const narrated = await attachNarrativeEvent(realitySave, {
          eventType: 'reality_travel',
          narrationKind: 'scene',
          title: result.message,
          playerIntent: result.message,
          authoritativeResult: '前端已确认现实地点移动，并保持现实世界为普通 2025 年中国。',
          previousLocationId,
          locationId: realitySave.map.currentLocationId,
          extraFacts: [`现实地点 ID：${action.locationId}`],
        });
        return success(narrated.save, `${result.message}${narrated.notice}`);
      }

      case 'REALITY_ACTION': {
        const result = performRealityAction(actionSave, action.actionId);
        const realitySave = recordMessage(result.save, 'system', result.message);
        const narrated = await attachNarrativeEvent(realitySave, {
          eventType: 'reality_action',
          narrationKind: 'scene',
          title: result.message,
          playerIntent: result.message,
          authoritativeResult: '前端已记录现实行动结果；现实世界仍保持普通 2025 年中国，不出现魔法或额外超现实接口。',
          locationId: realitySave.map.currentLocationId,
          extraFacts: [`现实行动 ID：${action.actionId}`],
        });
        return success(narrated.save, `${result.message}${narrated.notice}`);
      }

      case 'REALITY_RECORD_CLUE':
        return success(recordRealityClue(actionSave, action.clueId, action.source), '现实线索已记录。');

      case 'NPC_CONTACT': {
        const result = contactNpc(actionSave, action.npcId);
        const narrated = await attachNarrativeEvent(result.save, {
          eventType: 'npc_contact',
          narrationKind: 'npc',
          title: `接近${result.npc.name}`,
          playerIntent: `走近${result.npc.name}，准备观察或交谈。`,
          authoritativeResult: '前端已确认玩家与该 NPC 进入接触状态；本次不自动推进任务、奖励或地图移动。',
          locationId: result.npc.locationId,
          npcId: result.npc.id,
          npcName: result.npc.name,
          extraFacts: [
            `NPC 身份：${result.npc.title}`,
            `NPC 简述：${result.npc.description}`,
            '玩家可以继续自由输入对白、动作或追问；需要权威结算时再点击确认事件。',
          ],
        });
        return success(narrated.save, `已接近 ${result.npc.name}。${narrated.notice}`);
      }

      case 'NPC_DIALOGUE': {
        const trimmedInput = action.input.trim();
        if (!trimmedInput) return failure(actionSave, 'NPC 交谈内容不能为空。');
        const result = contactNpc(actionSave, action.npcId);
        const narrated = await attachNarrativeEvent(result.save, {
          eventType: 'npc_dialogue',
          narrationKind: 'npc',
          title: `与${result.npc.name}自由交谈`,
          playerIntent: `对${result.npc.name}说或做：${trimmedInput}`,
          authoritativeResult: '前端已确认本次是自由 NPC 交谈；没有自动结算任务、经验、金币、物品、地图移动或战斗胜负。',
          locationId: result.npc.locationId,
          npcId: result.npc.id,
          npcName: result.npc.name,
          topicLabel: '自由交谈',
          topicSeed: `玩家原文：${trimmedInput}`,
          extraFacts: [
            `NPC 身份：${result.npc.title}`,
            `NPC 世界书提示：${result.npc.worldbookHint}`,
            '正文可以写 NPC 对玩家内容的自然反应，也可以引出可点击的下一步，但不能直接完成未被前端确认的目标。',
          ],
        });
        return success(narrated.save, `已记录与 ${result.npc.name} 的自由交谈。${narrated.notice}`);
      }

      case 'NPC_TALK': {
        const result = talkToNpc(actionSave, action.npcId, action.topicId);
        const talkEventSave = applyQuestEvent(result.save, { kind: 'talk', npcId: result.npc.id });
        const nextSave = result.questEvent ? applyQuestEvent(talkEventSave, result.questEvent) : talkEventSave;
        const changedQuestIds = getChangedQuestIds(actionSave, nextSave);
        const narrated = await attachNarrativeEvent(nextSave, {
          eventType: 'npc_talk',
          narrationKind: result.topic.kind === 'quest' || changedQuestIds.length ? 'quest' : 'npc',
          title: `与${result.npc.name}谈${result.topic.label}`,
          playerIntent: `与${result.npc.name}谈起“${result.topic.label}”。`,
          authoritativeResult: `前端已记录 NPC 话题 ${result.topic.id}；${changedQuestIds.length ? `并推进任务：${changedQuestIds.join('、')}` : '本次没有额外任务结算。'}`,
          locationId: result.npc.locationId,
          npcId: result.npc.id,
          npcName: result.npc.name,
          topicId: result.topic.id,
          topicLabel: result.topic.label,
          topicSeed: result.topic.responseSeed,
          questId: changedQuestIds[0],
          extraFacts: [
            `话题摘要：${result.topic.summary}`,
            result.questEvent ? `话题携带任务事件：${result.questEvent.kind}` : '话题没有额外任务事件。',
          ],
        });
        return success(narrated.save, `已记录与 ${result.npc.name} 的话题：${result.topic.label}。${narrated.notice}`);
      }

      case 'NPC_GENERATE_SCENE_DRAFT':
        return success(await generateSceneNpcDraft(actionSave, action.locationId || actionSave.map.currentLocationId), '场景 NPC 草案已生成，确认后会写入世界书。');

      case 'WORLDBOOK_DRAFT_CONFIRM':
        return success(await confirmWorldbookDraft(actionSave, action.draftId), '世界书草案已写入当前存档世界书。');

      case 'WORLDBOOK_DRAFT_REJECT':
        return success(rejectWorldbookDraft(actionSave, action.draftId), '世界书草案已拒绝。');

      case 'NARRATION_GENERATE':
        return success(await generateNarrationFromInput(actionSave, action.input, action.kind || 'free'), '叙述已生成。');

      case 'STORY_SUMMARY_GENERATE': {
        const beforeCount = getUnsummarizedNarrationEntries(actionSave).length;
        const summarized = await summarizeStoryLogs(actionSave, { force: true });
        const afterCount = getUnsummarizedNarrationEntries(summarized).length;
        const error = summarized.narration.summary.lastError;
        if (error && beforeCount === afterCount) {
          return success(summarized, `大总结失败：${error}`);
        }
        return success(summarized, `大总结已更新，处理 ${beforeCount - afterCount} 条日志。`);
      }

      case 'ACHIEVEMENT_SYNC':
        return success(actionSave, '成就状态已同步。');

      case 'ACHIEVEMENT_GENERATE_DRAFT':
        return success(await generateAchievementDraft(actionSave), '成就草案已生成，确认后进入成就栏。');

      case 'ACHIEVEMENT_CONFIRM':
        return success(confirmAchievementDraft(actionSave, action.draftId), '成就已确认。');

      case 'ACHIEVEMENT_REJECT':
        return success(rejectAchievementDraft(actionSave, action.draftId), '成就草案已拒绝。');

      default:
        return failure(actionSave, '未知 Action。');
    }
  } catch (error) {
    return failure(save, error);
  }
}
