import { PLAYER_GENDER_LABELS, type GameSave, type PlayerProfile, type WorldbookDraft, type WorldbookMemoryRecord } from './types';
import { createId, nowIso } from './save';

function yamlQuote(value: string): string {
  return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

function yamlLiteralBlock(value: string, indent = 4): string {
  const normalized = value.trim();
  if (!normalized) return `${' '.repeat(indent)}""`;
  return normalized
    .split(/\r?\n/)
    .map(line => `${' '.repeat(indent)}${line}`)
    .join('\n');
}

export function buildPlayerProfileYaml(profile: Pick<PlayerProfile, 'username' | 'gender' | 'profileText'>): string {
  return [
    'player_profile:',
    `  project: ${yamlQuote('8bit的幻想')}`,
    `  username: ${yamlQuote(profile.username.trim())}`,
    `  gender: ${yamlQuote(PLAYER_GENDER_LABELS[profile.gender])}`,
    `  gender_code: ${yamlQuote(profile.gender)}`,
    '  detail: |-',
    yamlLiteralBlock(profile.profileText),
    '  authority:',
    '    - "用户名、性别、详细人设是当前存档的玩家身份根定义。"',
    '    - "你必须尊重此身份生成开场白、旁白、对白与 NPC 反应。"',
    '    - "你不得宣告经验、战斗、掉落、装备、任务、地图、职业等权威结果。"',
    '  immutable_rules:',
    '    - "{{user}} 是勇者。"',
    '    - "莱姆是女性魔王，但完整人设保留给用户。"',
    '    - "现实世界限定普通 2025 年中国，现实中剑与魔法无效。"',
    '    - "唯一超现实接口是 8 bit 手表。"',
  ].join('\n');
}

export function buildPlayerProfileWorldbookContent(profile: Pick<PlayerProfile, 'username' | 'gender' | 'profileText'>): string {
  return [
    '# 8bit的幻想 / 玩家现实身份',
    '# 此条目由前端在创建身份时自动写入当前聊天世界书。',
    '# 它是当前存档的角色根定义，开场白、现实行动、主叙述与 NPC 互动都应优先尊重。',
    buildPlayerProfileYaml(profile),
  ].join('\n');
}

function createConstantWorldbookEntry(name: string, content: string): PartialDeep<WorldbookEntry> {
  return {
    name,
    enabled: true,
    strategy: {
      type: 'constant',
      keys: [],
      keys_secondary: { logic: 'and_any', keys: [] },
      scan_depth: 'same_as_global',
    },
    position: {
      type: 'before_character_definition',
      role: 'system',
      depth: 0,
      order: 1,
    },
    content,
    probability: 100,
    recursion: {
      prevent_incoming: true,
      prevent_outgoing: true,
      delay_until: null,
    },
    effect: {
      sticky: null,
      cooldown: null,
      delay: null,
    },
    extra: {
      eightBitFantasy: {
        kind: 'player_profile',
        recursiveEnabledByDesign: true,
        preventRecursionByDesign: true,
      },
    },
  };
}

export async function bindWorldbookToSave(save: GameSave): Promise<GameSave> {
  const worldbookName = save.worldbookMemory.worldbookName;
  await getOrCreateChatWorldbook('current', worldbookName);
  await rebindChatWorldbook('current', worldbookName);
  return {
    ...save,
    worldbookMemory: {
      ...save.worldbookMemory,
      boundAtIso: nowIso(),
      lastSyncAtIso: nowIso(),
      lastError: undefined,
    },
  };
}

export async function restoreWorldbookForSave(save: GameSave): Promise<GameSave> {
  try {
    return await bindWorldbookToSave(save);
  } catch (error) {
    return {
      ...save,
      worldbookMemory: {
        ...save.worldbookMemory,
        lastError: error instanceof Error ? error.message : String(error),
      },
    };
  }
}

export async function writeWorldbookEntryForSave(
  save: GameSave,
  entry: PartialDeep<WorldbookEntry>,
  record: Omit<WorldbookMemoryRecord, 'id' | 'createdAtIso' | 'entryUid'>,
): Promise<{ save: GameSave; entry?: WorldbookEntry }> {
  const boundSave = await bindWorldbookToSave(save);
  const { new_entries } = await createWorldbookEntries(boundSave.worldbookMemory.worldbookName, [entry], { render: 'debounced' });
  const createdEntry = new_entries[0];
  return {
    save: {
      ...boundSave,
      worldbookMemory: {
        ...boundSave.worldbookMemory,
        lastSyncAtIso: nowIso(),
        records: [
          ...boundSave.worldbookMemory.records,
          {
            ...record,
            id: createId('wbr'),
            entryUid: createdEntry?.uid,
            createdAtIso: nowIso(),
          },
        ],
      },
    },
    entry: createdEntry,
  };
}

export async function writePlayerProfileToWorldbook(
  save: GameSave,
  profile: Pick<PlayerProfile, 'username' | 'gender' | 'profileText'>,
): Promise<{ save: GameSave; entry?: WorldbookEntry }> {
  const content = buildPlayerProfileWorldbookContent(profile);
  const entryName = `8bit的幻想: ${profile.username}现实身份`;
  return writeWorldbookEntryForSave(save, createConstantWorldbookEntry(entryName, content), {
    kind: 'player_profile',
    entryName,
    contentPreview: `${profile.username} / ${PLAYER_GENDER_LABELS[profile.gender]} / ${profile.profileText.trim()}`.slice(0, 180),
  });
}

export function createWorldbookDraft(save: GameSave, draft: Omit<WorldbookDraft, 'id' | 'createdAtIso' | 'status'>): GameSave {
  return {
    ...save,
    worldbookMemory: {
      ...save.worldbookMemory,
      drafts: [
        ...save.worldbookMemory.drafts,
        {
          ...draft,
          id: createId('wbd'),
          createdAtIso: nowIso(),
          status: 'pending',
        },
      ],
    },
  };
}

export async function confirmWorldbookDraft(save: GameSave, draftId: string): Promise<GameSave> {
  const draft = save.worldbookMemory.drafts.find(item => item.id === draftId);
  if (!draft || draft.status !== 'pending') return save;
  const { save: nextSave } = await writeWorldbookEntryForSave(
    save,
    createConstantWorldbookEntry(draft.entryName, draft.content),
    {
      kind: draft.kind,
      entryName: draft.entryName,
      contentPreview: draft.content.slice(0, 180),
    },
  );
  return {
    ...nextSave,
    worldbookMemory: {
      ...nextSave.worldbookMemory,
      drafts: nextSave.worldbookMemory.drafts.map(item => (item.id === draftId ? { ...item, status: 'accepted' } : item)),
    },
  };
}

export function rejectWorldbookDraft(save: GameSave, draftId: string): GameSave {
  return {
    ...save,
    worldbookMemory: {
      ...save.worldbookMemory,
      drafts: save.worldbookMemory.drafts.map(item => (item.id === draftId ? { ...item, status: 'rejected' } : item)),
    },
  };
}

export async function exportSaveWorldbookBundle(save: GameSave) {
  const entries = await getWorldbook(save.worldbookMemory.worldbookName);
  return {
    save,
    worldbook: {
      name: save.worldbookMemory.worldbookName,
      entries,
    },
    exportedAtIso: nowIso(),
  };
}

export async function importSaveWorldbookBundle(bundle: Awaited<ReturnType<typeof exportSaveWorldbookBundle>>): Promise<GameSave> {
  await createOrReplaceWorldbook(bundle.worldbook.name, bundle.worldbook.entries, { render: 'debounced' });
  await rebindChatWorldbook('current', bundle.worldbook.name);
  return {
    ...bundle.save,
    worldbookMemory: {
      ...bundle.save.worldbookMemory,
      worldbookName: bundle.worldbook.name,
      boundAtIso: nowIso(),
      lastSyncAtIso: nowIso(),
    },
  };
}
