import type { GameSave, WatchPanelId, WatchState } from './types';

export const DEFAULT_WATCH_PANELS: WatchPanelId[] = [
  'map',
  'status',
  'reality',
  'time',
  'combat',
  'party',
  'inventory',
  'equipment',
  'quest',
  'npc',
  'narration',
  'achievement',
  'debug',
  'settings',
];

export function createInitialWatchState(): WatchState {
  return {
    activePanel: 'map',
    unlockedPanels: DEFAULT_WATCH_PANELS,
  };
}

export function normalizeWatchState(raw: unknown): WatchState {
  if (!raw || typeof raw !== 'object') return createInitialWatchState();
  const candidate = raw as Partial<WatchState>;
  return {
    activePanel: candidate.activePanel && DEFAULT_WATCH_PANELS.includes(candidate.activePanel) ? candidate.activePanel : 'map',
    unlockedPanels: Array.from(new Set([...DEFAULT_WATCH_PANELS, ...(candidate.unlockedPanels || [])])),
    anchorLocationId: candidate.anchorLocationId,
  };
}

export function getUnlockedWatchPanels(save: GameSave): WatchPanelId[] {
  return save.watch.unlockedPanels;
}

export function setActiveWatchPanel(save: GameSave, panelId: WatchPanelId): GameSave {
  if (!save.watch.unlockedPanels.includes(panelId)) throw Error('该手表面板尚未解锁。');
  return {
    ...save,
    watch: {
      ...save.watch,
      activePanel: panelId,
    },
  };
}

export function setWatchAnchor(save: GameSave, locationId: string): GameSave {
  if (!save.map.unlockedLocationIds.includes(locationId)) throw Error('只能把复活锚点设置在已解锁地点。');
  return {
    ...save,
    watch: {
      ...save.watch,
      anchorLocationId: locationId,
    },
  };
}

export function getWatchAnchor(save: GameSave): string | undefined {
  return save.watch.anchorLocationId;
}

export function getWatchHint(save: GameSave): string {
  if (save.watch.activePanel === 'map') return '地图页显示当前位置、可移动目标和下一步提示。';
  if (save.watch.activePanel === 'status') return '状态页显示等级、经验、职业、技能和存档状态。';
  if (save.watch.activePanel === 'reality') return '现实页显示现实地点、线索、休息状态和世界暂停规则。';
  if (save.watch.activePanel === 'time') return '时间页显示设定时间、时间戳校验和时间推进日志。';
  if (save.watch.activePanel === 'combat') return '战斗页显示速度条、敌人状态、行动按钮和战斗记录。';
  if (save.watch.activePanel === 'inventory') return '背包页显示金币、消耗品、素材和装备物品。';
  if (save.watch.activePanel === 'equipment') return '装备页显示全装备槽、当前加成和可穿戴物品。';
  if (save.watch.activePanel === 'npc') return 'NPC 页显示当前位置角色、可聊话题和世界书草案。';
  if (save.watch.activePanel === 'narration') return '叙述页根据权威局势摘要请求正文旁白与对白。';
  if (save.watch.activePanel === 'achievement') return '成就页显示已确认成就和待确认草案。';
  if (save.watch.activePanel === 'debug') return '调试页显示存档健康、世界书、提示词注入、草案和安全 Action。';
  return '该手表功能会随主线和模块逐步扩展。';
}
