import {
  DEFAULT_API_PROFILE_ID,
  PROJECT_NAME,
  SAVE_SCHEMA_VERSION,
  SAVE_VARIABLE_KEY,
  type GameMessage,
  type GameSave,
  type PlayerGender,
  type PlayerProfile,
} from './types';
import { createInitialAchievementState, normalizeAchievementState } from './achievements';
import { createDefaultApiState, ensureApiState } from './apiProfiles';
import { createInitialCombatState, normalizeCombatState } from './combat';
import { createInitialContentRuntimeState, normalizeContentRuntimeState } from './content';
import { createInitialClock, normalizeClockState } from './clock';
import { createInitialEquipmentState, normalizeEquipmentState } from './equipment';
import { createInitialInventoryState, normalizeInventoryState } from './inventory';
import { createInitialMapState, normalizeMapState } from './map';
import { createInitialNarrationState, normalizeNarrationState } from './narration';
import { createInitialNpcState, normalizeNpcState } from './npcs';
import { normalizePlayerState } from './player';
import { createInitialQuestState, normalizeQuestState } from './quests';
import { createInitialRealityState, normalizeRealityState } from './reality';
import { createInitialWatchState, normalizeWatchState } from './watch';

let fallbackSave: GameSave | null = null;

export function nowIso(): string {
  return new Date().toISOString();
}

export function createId(prefix: string): string {
  const randomId =
    typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
      ? crypto.randomUUID()
      : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  return `${prefix}-${randomId}`;
}

export function createInitialGameSave(): GameSave {
  const createdAtIso = nowIso();
  const saveId = createId('save');
  const worldbookName = `${PROJECT_NAME}_${saveId}`;
  return {
    schemaVersion: SAVE_SCHEMA_VERSION,
    saveId,
    saveName: `${PROJECT_NAME} 存档`,
    stage: 'empty',
    createdAtIso,
    updatedAtIso: createdAtIso,
    worldMode: 'reality',
    playerState: undefined,
    clock: createInitialClock('reality'),
    opening: {
      status: 'waiting_profile',
      text: '',
    },
    watch: createInitialWatchState(),
    map: createInitialMapState(),
    reality: createInitialRealityState(),
    combat: createInitialCombatState(),
    inventory: createInitialInventoryState(),
    equipment: createInitialEquipmentState(),
    quests: createInitialQuestState(),
    npc: createInitialNpcState(),
    narration: createInitialNarrationState(),
    achievements: createInitialAchievementState(),
    worldbookMemory: {
      worldbookName,
      bindingMode: 'chat',
      records: [],
      drafts: [],
    },
    content: createInitialContentRuntimeState(),
    api: createDefaultApiState(createdAtIso),
    messages: [],
    debug: {
      errors: [],
    },
  };
}

function cloneSave(save: GameSave): GameSave {
  return JSON.parse(JSON.stringify(save)) as GameSave;
}

function normalizeIdentityText(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function inferLegacyUsername(profileText: string): string {
  const match = profileText.match(/(?:用户名|名字|姓名|称呼|角色名)\s*[:：]\s*([^\n,，。；;]+)/);
  const candidate = match?.[1]?.trim().replace(/^["'“”‘’《》]+|["'“”‘’《》]+$/g, '');
  return candidate || '{{user}}';
}

function inferLegacyGender(profileText: string): PlayerGender {
  const femaleHint = /女|女性|女生|女孩|少女|姐姐|妹妹/.test(profileText);
  const maleHint = /男|男性|男生|男孩|少年|哥哥|弟弟/.test(profileText);
  return femaleHint && !maleHint ? 'female' : 'male';
}

function normalizePlayerProfile(raw: unknown): PlayerProfile | undefined {
  if (!raw || typeof raw !== 'object') return undefined;
  const candidate = raw as Partial<PlayerProfile>;
  const profileText = normalizeIdentityText(candidate.profileText);
  const username = normalizeIdentityText(candidate.username) || inferLegacyUsername(profileText);
  const gender = candidate.gender === 'female' || candidate.gender === 'male' ? candidate.gender : inferLegacyGender(profileText);
  return {
    id: 'player',
    username,
    gender,
    profileText,
    createdAtIso: candidate.createdAtIso || nowIso(),
    worldbookEntryUid: candidate.worldbookEntryUid,
    worldbookEntryName: candidate.worldbookEntryName,
  };
}

function normalizeSave(raw: unknown): GameSave | null {
  if (!raw || typeof raw !== 'object') return null;
  const candidate = raw as Partial<GameSave>;
  if (candidate.schemaVersion !== SAVE_SCHEMA_VERSION || !candidate.saveId) return null;
  const updatedAtIso = nowIso();
  const save = candidate as GameSave;
  const player = normalizePlayerProfile(save.player);
  const normalizedBase = {
    ...save,
    player,
  };
  return {
    ...normalizedBase,
    updatedAtIso: save.updatedAtIso || updatedAtIso,
    clock: normalizeClockState(save.clock, save.worldMode || 'reality'),
    playerState: save.playerState ? normalizePlayerState(save.playerState) : player ? normalizePlayerState(null) : undefined,
    opening: save.opening || { status: player ? 'ready_for_ai' : 'waiting_profile', text: '' },
    watch: normalizeWatchState(save.watch),
    map: normalizeMapState(save.map),
    reality: normalizeRealityState(save.reality),
    combat: normalizeCombatState(save.combat),
    inventory: normalizeInventoryState(save.inventory),
    equipment: normalizeEquipmentState(save.equipment),
    quests: normalizeQuestState(save.quests),
    npc: normalizeNpcState(save.npc),
    narration: normalizeNarrationState(save.narration),
    achievements: normalizeAchievementState(save.achievements),
    worldbookMemory: save.worldbookMemory || {
      worldbookName: `${PROJECT_NAME}_${save.saveId}`,
      bindingMode: 'chat',
      records: [],
      drafts: [],
    },
    content: normalizeContentRuntimeState(save.content, normalizedBase as GameSave),
    api: ensureApiState(save.api || createDefaultApiState(updatedAtIso), updatedAtIso),
    messages: save.messages || [],
    debug: save.debug || { errors: [] },
  };
}

export function normalizeGameSave(raw: unknown): GameSave {
  const normalized = normalizeSave(raw);
  if (!normalized) throw Error('导入内容不是有效的 8bit的幻想存档。');
  return normalized;
}

export function exportGameSaveText(save: GameSave): string {
  return JSON.stringify(
    {
      kind: 'eight_bit_fantasy_save',
      exportedAtIso: nowIso(),
      save,
    },
    null,
    2,
  );
}

export function importGameSaveText(rawText: string): GameSave {
  const parsed = JSON.parse(rawText);
  return normalizeGameSave(parsed?.save || parsed);
}

function readChatVariableSave(): GameSave | null {
  if (typeof getVariables !== 'function') return fallbackSave;
  const variables = getVariables({ type: 'chat' });
  const stored = variables[SAVE_VARIABLE_KEY];
  const parsed = typeof stored === 'string' ? JSON.parse(stored) : stored;
  return normalizeSave(parsed);
}

export function loadGameSave(): GameSave {
  try {
    const existing = readChatVariableSave();
    if (existing) return existing;
  } catch {
    // Broken saves are handled by creating a clean one; M12 will expose repair UI.
  }

  const save = createInitialGameSave();
  persistGameSave(save);
  return save;
}

export function persistGameSave(save: GameSave): GameSave {
  const nextSave = cloneSave({
    ...save,
    updatedAtIso: nowIso(),
    api: ensureApiState(save.api, nowIso()),
  });

  fallbackSave = nextSave;

  if (typeof getVariables === 'function' && typeof replaceVariables === 'function') {
    const variables = getVariables({ type: 'chat' });
    variables[SAVE_VARIABLE_KEY] = nextSave;
    replaceVariables(variables, { type: 'chat' });
  }

  return nextSave;
}

export function recordMessage(save: GameSave, role: GameMessage['role'], text: string): GameSave {
  return {
    ...save,
    messages: [
      ...save.messages,
      {
        id: createId('msg'),
        role,
        text,
        createdAtIso: nowIso(),
      },
    ],
  };
}

export function recordDebugError(save: GameSave, error: unknown): GameSave {
  const text = error instanceof Error ? error.message : String(error);
  return {
    ...save,
    debug: {
      ...save.debug,
      errors: [text, ...save.debug.errors].slice(0, 20),
    },
  };
}
