const EQUIPMENT_BY_ID = new Map(EQUIPMENT_DEFINITIONS.map(item => [item.itemId, item]));

export function createInitialEquipmentState(): EquipmentState {
  return {
    equipped: {
      weapon: 'wooden_sword',
      body: 'patched_cloth',
    },
  };
}

export function normalizeEquipmentState(raw: unknown): EquipmentState {
  const fallback = createInitialEquipmentState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<EquipmentState>;
  const equipped: Partial<Record<EquipmentSlot, string>> = {};
  Object.entries(candidate.equipped || {}).forEach(([slot, itemId]) => {
    if (!EQUIPMENT_SLOT_ORDER.includes(slot as EquipmentSlot)) return;
    if (typeof itemId !== 'string') return;
    if (!EQUIPMENT_BY_ID.has(itemId)) return;
    equipped[slot as EquipmentSlot] = itemId;
  });
  return { equipped };
}

export function getEquipmentDefinition(itemId: string): EquipmentDefinition | undefined {
  return EQUIPMENT_BY_ID.get(itemId);
}

export function isEquipmentItem(itemId: string): boolean {
  return EQUIPMENT_BY_ID.has(itemId);
}

function createEmptyAttributeBlock(value = 0): PlayerAttributeBlock {
  return {
    strength: value,
    constitution: value,
    intelligence: value,
    spirit: value,
    agility: value,
    technique: value,
    luck: value,
    will: value,
  };
}

function addAttributes(left: PlayerAttributeBlock, right: Partial<PlayerAttributeBlock>): PlayerAttributeBlock {
  const next = { ...left };
  Object.keys(next).forEach(key => {
    const attributeKey = key as keyof PlayerAttributeBlock;
    next[attributeKey] += right[attributeKey] || 0;
  });
  return next;
}

function countInventoryItem(save: GameSave, itemId: string): number {
  return save.inventory.items.find(item => item.itemId === itemId)?.count || 0;
}

function countEquippedItem(equipment: EquipmentState, itemId: string): number {
  return Object.values(equipment.equipped).filter(value => value === itemId).length;
}

export function getEquipmentAttributeBonus(save: GameSave): PlayerAttributeBlock {
  const equipment = normalizeEquipmentState(save.equipment);
  return Object.values(equipment.equipped).reduce((bonus, itemId) => {
    const definition = itemId ? getEquipmentDefinition(itemId) : undefined;
    return definition ? addAttributes(bonus, definition.attributes) : bonus;
  }, createEmptyAttributeBlock());
}

export function getEquipmentSlotViews(save: GameSave): EquipmentSlotView[] {
  const equipment = normalizeEquipmentState(save.equipment);
  return EQUIPMENT_SLOT_ORDER.map(slot => {
    const itemId = equipment.equipped[slot];
    return {
      slot,
      label: EQUIPMENT_SLOT_LABELS[slot],
      itemId,
      definition: itemId ? getEquipmentDefinition(itemId) : undefined,
    };
  });
}

export function getEquipCandidates(save: GameSave, slot?: EquipmentSlot): EquipmentDefinition[] {
  const equipment = normalizeEquipmentState(save.equipment);
  return save.inventory.items
    .filter(item => item.kind === 'equipment' && item.count > countEquippedItem(equipment, item.itemId))
    .map(item => getEquipmentDefinition(item.itemId))
    .filter((item): item is EquipmentDefinition => Boolean(item))
    .filter(item => !slot || item.slotOptions.includes(slot));
}

export function equipInventoryItem(save: GameSave, itemId: string, preferredSlot?: EquipmentSlot): GameSave {
  const definition = getEquipmentDefinition(itemId);
  if (!definition) throw Error('这个物品不能装备。');

  const equipment = normalizeEquipmentState(save.equipment);
  if (countInventoryItem(save, itemId) <= countEquippedItem(equipment, itemId)) {
    throw Error('背包里没有可装备的这件物品。');
  }

  const slot = preferredSlot && definition.slotOptions.includes(preferredSlot)
    ? preferredSlot
    : definition.slotOptions[0];
  if (!slot) throw Error('这个装备没有可用槽位。');

  return {
    ...save,
    equipment: {
      equipped: {
        ...equipment.equipped,
        [slot]: itemId,
      },
    },
  };
}

export function unequipInventorySlot(save: GameSave, slot: EquipmentSlot): GameSave {
  const equipment = normalizeEquipmentState(save.equipment);
  if (!equipment.equipped[slot]) return save;
  const equipped = { ...equipment.equipped };
  delete equipped[slot];
  return {
    ...save,
    equipment: {
      equipped,
    },
  };
}
